# ═════════ STEP 1 — Connect Google Drive and check the CLEVRER folder  (≈1 min) ═════════
# Choose the Google account that OWNS the CLEVRER folder, or one with Editor access and a
# "CLEVRER" shortcut in its My Drive. To switch accounts set SWITCH_ACCOUNT = True and rerun.
# RESUME after a disconnect / new session: Runtime → Run all. Everything continues where it stopped.
SWITCH_ACCOUNT = False
FREE_TIER_HOURS = "auto" # session length: "auto" = 22 h on a paid L4/A100/H100, 5 h otherwise (free T4); or a number
SAFETY_MINUTES = 15      # STEP 5 stops starting/continuing work this long before the session end
UNATTENDED = True        # nobody watching: if ANY later cell fails, the GPU is released after 2 min (saves compute
                         # units). Set False while you are debugging interactively.

import os, sys, time, json, shutil, contextlib, subprocess
from pathlib import Path
from google.colab import drive
if FREE_TIER_HOURS == "auto":
    try:
        _gpu = subprocess.run(["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"], capture_output=True,
                              text=True, timeout=20).stdout.strip()
    except (OSError, subprocess.SubprocessError):
        _gpu = ""
    FREE_TIER_HOURS = 22.0 if any(g in _gpu for g in ("L4", "A100", "H100")) else 5.0
    print(f"GPU: {_gpu or 'none'} → planning a {FREE_TIER_HOURS:g} h session"
          + ("" if _gpu else "  ⚠ no GPU: Runtime → Change runtime type → L4"))


@contextlib.contextmanager
def step(title):
    """Prints a clear start/finish line for every stage and a readable message on failure."""
    t0 = time.time()
    print(f"▶ {title} ...", flush=True)
    try:
        yield
    except Exception as e:
        print(f"✗ {title} FAILED after {time.time()-t0:.0f}s → {type(e).__name__}: {e}", flush=True)
        raise
    print(f"✓ {title} ({time.time()-t0:.0f}s)", flush=True)


# Session clock = when this Colab runtime started (installs and setup count against the session too).
# The start is stored once per runtime in /content (wiped with every new runtime), so rerunning cells keeps it.
_clock = Path("/content/.nexvip_session_start")
try:
    SESSION_START = float(_clock.read_text())
except (OSError, ValueError):
    try:
        _up = float(open("/proc/uptime").read().split()[0])
    except OSError:
        _up = 0.0
    if _up > 45 * 60:   # cannot be this runtime's own boot (e.g. a container reporting host uptime)
        print("   note: cannot tell when this runtime started; the session clock starts now.")
        _up = 0.0
    SESSION_START = time.time() - _up
    try:
        _clock.write_text(repr(SESSION_START))
    except OSError:
        pass


def session_left_s():
    """Seconds until STEP 5 must have stopped (session length − safety margin)."""
    return SESSION_START + FREE_TIER_HOURS * 3600 - SAFETY_MINUTES * 60 - time.time()


print(f"Session clock: started {(time.time()-SESSION_START)/60:.0f} min ago · budget {FREE_TIER_HOURS:g} h "
      f"− {SAFETY_MINUTES} min safety → {max(0, session_left_s())/3600:.1f} h of work left in this session")

with step("Mounting Google Drive"):
    if SWITCH_ACCOUNT or not Path("/content/drive/MyDrive").is_dir():
        drive.mount("/content/drive", force_remount=SWITCH_ACCOUNT)


def _release_gpu_on_error(result):
    """Unattended safety net: a failed cell stops 'Run all', which would leave a paid GPU idle for hours."""
    err = result.error_in_exec or result.error_before_exec
    if not globals().get("UNATTENDED") or err is None or isinstance(err, KeyboardInterrupt):
        return
    print(f"\n⛔ A step failed while running unattended ({type(err).__name__}). Everything finished so far is saved on "
          "Drive (see RUN_STATUS.md / analysis/job_errors.jsonl). Releasing the GPU in 120 s — interrupt to keep it.",
          flush=True)
    try:
        time.sleep(120)
        if "_wait_uploads" in globals():
            globals()["_wait_uploads"]()             # never cut off a checkpoint upload in flight
    except KeyboardInterrupt:
        print("GPU kept.")
        return
    except Exception:                                # noqa: BLE001
        pass
    from google.colab import runtime
    runtime.unassign()


if not globals().get("_GPU_GUARD_ON"):
    get_ipython().events.register("post_run_cell", _release_gpu_on_error)
    _GPU_GUARD_ON = True
    print("Unattended guard on: if a step fails, the GPU is released after 2 min (UNATTENDED = False to disable)."
          if UNATTENDED else "Unattended guard off (UNATTENDED = False).")

BASE = Path("/content/drive/MyDrive/CLEVRER")
OLD = BASE / "NEXVIP_SCIENTIFIC_REVISION"
ROOT = BASE / "NEXVIP_REVIEWER_REVISION_V2"
LOCAL = Path("/content/nexvip_revision_v2")
CODE = LOCAL / "code"

with step("Checking the CLEVRER folder"):
    if not BASE.is_dir():
        raise FileNotFoundError("MyDrive/CLEVRER not found. Mount the owner account (SWITCH_ACCOUNT=True) "
                                "or add a shortcut named CLEVRER to My Drive with Editor access.")
    for folder in (ROOT, LOCAL, CODE):
        folder.mkdir(parents=True, exist_ok=True)
    probe = ROOT / "drive_write_probe.tmp"
    probe.write_text("ok")
    probe.unlink()   # fails here if the account only has Viewer access
    checks = {
        "derender_proposals.zip (object metrics)": (BASE / "derender_proposals.zip").is_file(),
        "original split / legacy folder": OLD.is_dir(),
        "saved split manifests": any((ROOT / "splits").glob("*.json")),
        "complete frame cache": any((ROOT / "caches").glob("*/spec.json")),
        "experiment queue": (ROOT / "experiment_queue.json").is_file(),
        "video_train.zip (only needed without a cache)": (BASE / "video_train.zip").is_file(),
    }
    for name, ok in checks.items():
        print(("   OK       " if ok else "   MISSING  ") + name)
    runs = [p for p in (ROOT / "runs").glob("*") if (p / "config.json").exists()]
    print(f"   Runs: {len(runs)} started · {sum((p/'DONE.json').exists() for p in runs)} trained · "
          f"{sum((p/'EVALUATED.json').exists() for p in runs)} evaluated")
    try:   # resume summary: the job that was running when the last session ended
        cur = json.loads((ROOT / "current_run.json").read_text())
        run = (ROOT / "mmnist" / "runs" if cur.get("dataset") == "mmnist" else ROOT / "runs") / cur["run_id"]
        cfg = json.loads((run / "config.json").read_text())
        state = ("evaluated" if (run / "EVALUATED.json").exists() else "trained, evaluation pending"
                 if (run / "DONE.json").exists() else "training in progress")
        line = (f"   Resume point: {'Moving MNIST ' if cur.get('dataset') == 'mmnist' else ''}{cfg['name']} "
                f"seed {cfg['seed']} ({cfg['loss']}) → {state}")
        if (run / "progress.json").exists() and state == "training in progress":
            p = json.loads((run / "progress.json").read_text())
            line += (f", epoch {min(p['epoch']+1, p['epochs'])}/{p['epochs']}, batch {p['next_batch']}/"
                     f"{p['updates_per_epoch']} (saved {(time.time()-p['saved_at'])/3600:.1f} h ago)")
        print(line)
    except (OSError, ValueError, KeyError):
        pass
    try:
        u = shutil.disk_usage("/content/drive")
        print(f"   Drive free space reported by the mount: {u.free/1e9:.1f} GB")
    except OSError:
        pass
print("Next: run STEP 2.")

