"""## STEP 3 — Load the CLEVRER split and frame cache"""

# ═════════ STEP 3 — Load the frozen split and the frame cache from Drive  (≈5–15 min first time per runtime) ═════════
# Copies the 64×64 frame cache with 16 threads and checks every file's SHA-256. No video ZIP needed.
from concurrent.futures import ThreadPoolExecutor, as_completed
from tqdm.auto import tqdm
from common import digest, sha, restore_archive
from data import make_manifest, build_cache

COPY_THREADS = 16


def load_saved_manifest(dataset, split_seed):
    found = []
    for p in sorted((ROOT / "splits").glob("*.json")):
        try:
            m = json.loads(p.read_text())
        except ValueError:
            continue
        if not isinstance(m, dict) or m.get("dataset") != dataset or m.get("split_seed") != split_seed:
            continue
        if "id" in m and digest({k: v for k, v in m.items() if k != "id"})[:16] == m["id"]:
            found.append(m)
    if len({m["id"] for m in found}) > 1:
        raise RuntimeError(f"Several saved manifests for {dataset}/{split_seed}")
    return found[0] if found else None


def find_complete_cache(manifest, frames=96):
    need = set(manifest["training_pool"]) | set(manifest["eval"])
    hits = []
    for spec_path in sorted((ROOT / "caches").glob("*/spec.json")):
        spec, folder = json.loads(spec_path.read_text()), spec_path.parent
        if spec.get("dataset") != manifest["dataset"] or spec.get("frames") != frames:
            continue
        if digest(spec)[:16] != folder.name or not (folder / "index.json").exists():
            continue
        index = json.loads((folder / "index.json").read_text())
        if need.issubset(index):
            hits.append((folder, spec, index))
    if len(hits) > 1:
        raise RuntimeError("Several complete caches match: " + str([h[0].name for h in hits]))
    return hits[0] if hits else None


def restore_cache_locally(folder, index, rels):
    local = LOCAL / "caches" / folder.name
    local.mkdir(parents=True, exist_ok=True)

    def one(rel):
        meta = index[rel]
        lp, pp = local / meta["file"], folder / meta["file"]
        if lp.exists() and sha(lp) == meta["sha256"]:
            return 0
        tmp = lp.with_name(lp.name + ".partial")
        shutil.copyfile(pp, tmp)
        if sha(tmp) != meta["sha256"]:
            tmp.unlink(missing_ok=True)
            raise IOError("Cache file failed verification: " + rel)
        os.replace(tmp, lp)
        return 1

    copied = 0
    with ThreadPoolExecutor(COPY_THREADS) as pool:
        futures = [pool.submit(one, r) for r in sorted(rels)]
        for f in tqdm(as_completed(futures), total=len(futures), desc="  copying + verifying cache",
                      unit="video", dynamic_ncols=True):
            copied += f.result()
    print(f"   {len(rels)} videos verified, {copied} copied from Drive")
    return local


def ensure_video_root():
    global VIDEO_ROOT
    if globals().get("VIDEO_ROOT") is None:
        print("   Restoring video_train.zip (needed once for a split manifest not saved yet; slow)...")
        VIDEO_ROOT = restore_archive(BASE / "video_train.zip", "clevrer_videos")
    return VIDEO_ROOT


def manifest_for(split_seed, dataset="clevrer"):
    m = load_saved_manifest(dataset, split_seed)
    return m if m is not None else make_manifest(ensure_video_root(), dataset, split_seed=split_seed)


VIDEO_ROOT = globals().get("VIDEO_ROOT")
with step("Loading the frozen original split and frame cache"):
    print(f"   local disk free: {shutil.disk_usage('/content').free/1e9:.0f} GB")
    MANIFEST = load_saved_manifest("clevrer", 20260817)
    hit = find_complete_cache(MANIFEST) if MANIFEST else None
    if hit:
        folder, spec, index = hit
        local = restore_cache_locally(folder, index, set(MANIFEST["training_pool"]) | set(MANIFEST["eval"]))
        CACHE = {"id": folder.name, "local": str(local), "index": index, "spec": spec}
    else:
        print("   No complete saved cache found → building it from video_train.zip (slow, one time).")
        VIDEO_ROOT = restore_archive(BASE / "video_train.zip", "clevrer_videos")
        MANIFEST = make_manifest(VIDEO_ROOT)
        CACHE = build_cache(VIDEO_ROOT, MANIFEST, frames=96)
    PROPOSALS = BASE / "derender_proposals.zip"
    if not PROPOSALS.exists():
        print("   derender_proposals.zip missing → object metrics will be unavailable.")
        PROPOSALS = None
    print("   train / validation / evaluation videos:", *[len(MANIFEST[k]) for k in ["train", "validation", "eval"]])
    print("   split id:", MANIFEST["id"], "| cache id:", CACHE["id"])
print("Next: run STEP 3B (KTH), then STEP 3C, then STEP 4.")

"""## STEP 3B — Load KTH (second dataset)"""

# ═════════ STEP 3B — Load the KTH second dataset (subject-disjoint split)  (≈2–10 min first time per runtime) ═════════
# Reuses the KTH split and frame cache saved on Drive. Only if they are missing does it download the
# official KTH archives (≈1.2 GB, non-commercial licence) and build them once.
# Skip this step only if you do not want KTH jobs in this session (they are then shown as "waiting").
KTH_SPLIT_SEED = 20260817

try:
  with step("Loading the KTH split and frame cache"):
      KTH_MANIFEST = load_saved_manifest("kth", KTH_SPLIT_SEED)
      hit = find_complete_cache(KTH_MANIFEST) if KTH_MANIFEST else None
      if hit:
          folder, spec, index = hit
          local = restore_cache_locally(folder, index, set(KTH_MANIFEST["training_pool"]) | set(KTH_MANIFEST["eval"]))
          KTH_CACHE = {"id": folder.name, "local": str(local), "index": index, "spec": spec}
      else:
          print("   No saved KTH cache found → downloading KTH and building the cache (one time).")
          from reporting import prepare_kth
          KTH_ROOT, KTH_MANIFEST = prepare_kth()
          KTH_CACHE = build_cache(KTH_ROOT, KTH_MANIFEST, frames=96)
      print("   KTH train / validation / evaluation videos:", *[len(KTH_MANIFEST[k]) for k in ["train", "validation", "eval"]])
      print("   KTH split id:", KTH_MANIFEST["id"], "| cache id:", KTH_CACHE["id"])
except Exception as _kth_err:          # noqa: BLE001 — never stop 'Run all' here: KTH jobs then wait
    KTH_CACHE = None
    print(f"⚠ KTH not available in this session ({type(_kth_err).__name__}: {_kth_err}). KTH jobs wait; "
          "everything else runs. Rerun STEP 3B later.")
print("Next: run STEP 3C (Moving MNIST), then STEP 4.")

"""## STEP 3C — Moving MNIST: standard 10→10 benchmark (data + runner)"""

# ═════════ STEP 3C — Moving MNIST: the standard benchmark (10 → 10 frames, 64×64, 2 digits)  (≈1–3 min first time) ═════════
# Why: CLEVRER (own split) and KTH (own 4→10 protocol) cannot be compared with published numbers. Moving MNIST
# with the standard protocol can: 10 context frames → 10 predicted frames, evaluated on the standard public
# test file (10,000 sequences, Srivastava et al., ICML 2015). Training sequences are generated on the fly from
# MNIST training digits (digits 0–49,999); validation uses 1,000 fixed sequences from held-out digits
# 50,000–59,999. Checkpoints are chosen on validation only; the test file is used once per run.
# Models: NEX-ViP with protocol-adapted input/output layers (10 grey frames in, 1 grey frame out; every other
# layer identical), TAU and SimVP-gSTA (OpenSTL, standard 10→10 configuration). All share one budget (20 epochs)
# and the CLEVRER base objective (L1+SSIM). Each model keeps the loss and learning rate chosen for it on CLEVRER
# validation: NEX-ViP its gate-1 auxiliary loss; each baseline plain or auxiliary loss and its lr. Nothing is
# tuned on Moving MNIST (no test-set tuning); the transfer is stated in the report.
# Metrics follow the common reporting convention: MSE and MAE summed over the 64×64 pixels and averaged over
# frames, SSIM and PSNR averaged over frames, plus skill vs copying the last input frame.
MMNIST_ENABLED = True
MM_EPOCHS = 20               # same epoch count as every other run; 10,000 generated sequences per epoch
MM_BATCH = 16                # standard Moving MNIST batch size
MM_TRAIN_SEQ = 10_000
MM_VAL_SEQ = 1_000
MM_MODELS = None             # None = the compute tier's default (critical: NEX-ViP + TAU; full: + SimVP-gSTA)
MM_SEEDS = [2024, 2025, 2026]
MM_TEST_URLS = ["https://www.cs.toronto.edu/~nitish/unsupervised_video/mnist_test_seq.npy",
                "http://www.cs.toronto.edu/~nitish/unsupervised_video/mnist_test_seq.npy"]   # https first
MM_DIGITS_URLS = ["https://storage.googleapis.com/tensorflow/tf-keras-datasets/mnist.npz"]
MM_TEST_SHA256 = None                   # pin after the first download (printed below); then every reload is verified
MM_DIGITS_SHA256 = "731c5ac602752760c8e48fbffcf8c3b850d9dc2a2aedcf2cc48468fc17b673d1"  # Keras mnist.npz file_hash
                                        # (set to None only if Keras changed the file and you checked the new one)
MM_PROTOCOL = "mmnist_standard_10to10_64px_2digits_v1"

import gc, math, os, time, json, shutil, urllib.request
from tqdm.auto import tqdm
from concurrent.futures import ThreadPoolExecutor
import numpy as np
import pandas as pd
import torch
from torch import nn
from common import sha, digest, atomic_json, atomic_csv

MM_ROOT = ROOT / "mmnist"
MM_LOCAL = LOCAL / "mmnist"


def _download(urls, dest, expected_sha=None):
    """Try each URL; reject truncated files (Content-Length) and hash mismatches; atomic rename."""
    errors = []
    for url in urls:
        tmp = dest.with_suffix(dest.suffix + ".part")
        try:
            with urllib.request.urlopen(url, timeout=120) as r, open(tmp, "wb") as f:
                n = int(r.headers.get("Content-Length", -1))
                shutil.copyfileobj(r, f, length=1 << 22)
            if n >= 0 and tmp.stat().st_size != n:
                raise IOError(f"truncated download ({tmp.stat().st_size} of {n} bytes)")
            if expected_sha and sha(tmp) != expected_sha:
                raise IOError("SHA-256 mismatch: not the expected file")
            tmp.replace(dest)
            return url
        except Exception as e:
            errors.append(f"{url}: {type(e).__name__}: {e}")
            tmp.unlink(missing_ok=True)
    raise IOError("download failed: " + " | ".join(errors))


def mm_load_data():
    """Standard test file + MNIST digits. Saved once on Drive (compressed, written atomically), restored locally."""
    MM_ROOT.mkdir(parents=True, exist_ok=True)
    MM_LOCAL.mkdir(parents=True, exist_ok=True)
    store, prov = MM_ROOT / "mmnist_data_v1.npz", MM_ROOT / "data_provenance.json"
    if not (store.exists() and prov.exists()):
        raw_test, raw_digits = MM_LOCAL / "mnist_test_seq.npy", MM_LOCAL / "mnist.npz"
        used_test = used_digits = "local copy"
        if not raw_test.exists():
            used_test = _download(MM_TEST_URLS, raw_test, MM_TEST_SHA256)
        if not raw_digits.exists():
            used_digits = _download(MM_DIGITS_URLS, raw_digits, MM_DIGITS_SHA256)
        test = np.load(raw_test, allow_pickle=False)          # (20, 10000, 64, 64) uint8, standard layout
        if test.shape != (20, 10000, 64, 64) or test.dtype != np.uint8:
            raise ValueError(f"Unexpected Moving MNIST test file {test.shape} {test.dtype}")
        with np.load(raw_digits, allow_pickle=False) as d:
            digits = d["x_train"]                             # (60000, 28, 28) uint8
        meta = {"test_source": used_test, "test_sha256": sha(raw_test), "test_bytes": raw_test.stat().st_size,
                "digits_source": used_digits, "digits_sha256": sha(raw_digits),
                "digits_sha256_verified": bool(MM_DIGITS_SHA256), "test_sha256_pinned": bool(MM_TEST_SHA256),
                "train_digits": "MNIST x_train[0:50000]", "validation_digits": "MNIST x_train[50000:60000]"}
        tmp = MM_LOCAL / "store.npz"
        np.savez_compressed(tmp, test=test.transpose(1, 0, 2, 3), digits=digits)   # test → (10000, 20, 64, 64)
        del test, digits
        atomic_json(prov, meta)
        shutil.copy2(tmp, store.with_name(store.name + ".partial"))
        os.replace(store.with_name(store.name + ".partial"), store)
        if not MM_TEST_SHA256:
            print(f"   Moving MNIST test file SHA-256: {meta['test_sha256']}\n   → pin it: set MM_TEST_SHA256 to this "
                  "value (after checking it against a second copy) and report it in the paper.")
    meta = json.loads(prov.read_text())
    if MM_TEST_SHA256 and meta["test_sha256"] != MM_TEST_SHA256:
        raise IOError("Stored Moving MNIST test file does not match MM_TEST_SHA256")
    local = MM_LOCAL / "store.npz"
    if not local.exists() or local.stat().st_size != store.stat().st_size:
        shutil.copy2(store, local)
    with np.load(local, allow_pickle=False) as z:
        return {"test": z["test"], "digits": z["digits"], "provenance": meta}


def mm_sequence(rng, digits, n_frames=20, size=64, n_digits=2, step=0.1):
    """Bouncing-digit sequence in the standard Moving MNIST style (2 digits, 28×28, max-composited)."""
    lim = size - 28
    out = np.zeros((n_frames, size, size), np.uint8)
    for _ in range(n_digits):
        img = digits[rng.integers(len(digits))]
        theta = rng.uniform(0, 2 * np.pi)
        y, x = rng.uniform(0, 1, 2)
        vy, vx = np.sin(theta), np.cos(theta)
        for t in range(n_frames):
            top, left = int(round(y * lim)), int(round(x * lim))
            np.maximum(out[t, top:top + 28, left:left + 28], img, out=out[t, top:top + 28, left:left + 28])
            y, x = y + vy * step, x + vx * step
            if y <= 0 or y >= 1:
                vy, y = -vy, min(max(y, 0.0), 1.0)
            if x <= 0 or x >= 1:
                vx, x = -vx, min(max(x, 0.0), 1.0)
    return out


def mm_batch(data, split, seed, epoch, indices):
    """(B, 20, 1, 64, 64) float in [0, 1]. Train/validation sequences depend only on (split, seed, epoch, index)."""
    if split == "test":
        arr = data["test"][indices]
    else:
        pool = data["digits"][:50_000] if split == "train" else data["digits"][50_000:]
        tag = 1 if split == "train" else 2                # validation: fixed sequences, independent of seed/epoch
        key = (lambda i: [tag, seed, epoch, int(i)]) if split == "train" else (lambda i: [tag, 0, 0, int(i)])
        arr = np.stack([mm_sequence(np.random.default_rng(key(i)), pool)
                        for i in indices])
    return torch.from_numpy(arr).float().div_(255).unsqueeze(2)


class MMNEX(nn.Module):
    """NEX-ViP with protocol-adapted I/O: input 10 grey frames (10 channels), output 1 grey frame.
    Encoder, transition and decoder widths are identical to the CLEVRER model."""
    def __init__(self, variant="full", context=10):
        super().__init__()
        self.context, self.variant = context, variant
        self.encoder = nn.Sequential(nn.Conv2d(context, 64, 4, 2, 1), nn.LeakyReLU(0.2),
                                     nn.Conv2d(64, 128, 4, 2, 1), nn.LeakyReLU(0.2),
                                     nn.Conv2d(128, 256, 4, 2, 1), nn.LeakyReLU(0.2), nn.Flatten(),
                                     nn.Linear(16384, 512))
        self.transition = nn.Identity() if variant == "identity" else nn.Sequential(
            nn.Linear(512, 512), nn.ReLU(), nn.Linear(512, 512))
        self.decoder = nn.Sequential(nn.Linear(512, 16384), nn.ReLU(), nn.Unflatten(1, (256, 8, 8)),
                                     nn.ConvTranspose2d(256, 128, 4, 2, 1), nn.ReLU(),
                                     nn.ConvTranspose2d(128, 64, 4, 2, 1), nn.ReLU(),
                                     nn.ConvTranspose2d(64, 1, 4, 2, 1), nn.Tanh())

    def step(self, x):                                   # x: (B, 10, 1, 64, 64) → next frame (B, 1, 64, 64)
        d = self.decoder(self.transition(self.encoder(x.flatten(1, 2))))
        return (x[:, -1] + d).clamp(0, 1)

    def forward(self, x, horizon=10):
        out, cur = [], x
        for _ in range(horizon):
            nxt = self.step(cur)
            out.append(nxt)
            cur = torch.cat((cur[:, 1:], nxt[:, None]), 1)
        return torch.stack(out, 1)


class MMOpenSTL(nn.Module):
    """TAU / SimVP-gSTA from OpenSTL in the standard 10→10 Moving MNIST shape."""
    def __init__(self, name):
        super().__init__()
        from openstl.models.simvp_model import SimVP_Model
        self.net = SimVP_Model(in_shape=(10, 1, 64, 64), hid_S=64, hid_T=512, N_S=4, N_T=8,
                               model_type={"tau": "tau", "simvpv2_gsta": "gSTA"}[name], mlp_ratio=8.0, drop=0.0,
                               drop_path=0.0, spatio_kernel_enc=3, spatio_kernel_dec=3)

    def forward(self, x, horizon=10):
        if horizon != 10:
            raise ValueError("Moving MNIST protocol predicts exactly 10 frames")
        return self.net(x.contiguous())


def mm_model(name):
    if name == "persistence":
        return None
    if name.startswith("nex_"):
        return MMNEX(name[4:])
    return MMOpenSTL(name)


def mm_metrics(pred, target, last):
    """Per-sequence metrics (B,) averaged over the 10 frames: MSE/MAE summed over pixels, SSIM, PSNR,
    plus copy-last-frame MSE for skill."""
    p, t = pred.float().clamp(0, 1), target.float()
    b, T = p.shape[:2]
    mse_f = (p - t).square().flatten(2).sum(2)          # (B, T) summed over pixels
    mae_f = (p - t).abs().flatten(2).sum(2)
    copy_f = (last.float()[:, None] - t).square().flatten(2).sum(2)
    ssim_f = _ssim_fn(p.flatten(0, 1), t.flatten(0, 1), data_range=1.0, reduction="none").view(b, T)
    psnr_f = 10 * torch.log10(1.0 / (p - t).square().flatten(2).mean(2).clamp_min(1e-10))
    return {"mse": mse_f.mean(1), "mae": mae_f.mean(1), "ssim": ssim_f.mean(1), "psnr": psnr_f.mean(1),
            "mse_copy": copy_f.mean(1), "mse_by_frame": mse_f, "copy_by_frame": copy_f}



# ----------------------------------------------------------------- runner (used by STEP 5; resumable, deadline-aware)
MM_CHECKPOINT_SECONDS = 1800
MM_TEST_CHUNK = 1000          # test sequences per saved part (evaluation resumes part by part)


def mm_config(job):
    return {"protocol": MM_PROTOCOL, "name": job["name"], "seed": job["seed"], "epochs": MM_EPOCHS,
            "batch": MM_BATCH, "train_seq": MM_TRAIN_SEQ, "val_seq": MM_VAL_SEQ, "loss": job["loss_kind"],
            "lr": float(job["lr"]), "weight_decay": 1e-4, "precision": job.get("precision", "fp32"),
            "test_sha256": MM_DATA["provenance"]["test_sha256"]}


def mm_find_run(job):
    if globals().get("MM_DATA") is None:
        return None, "waiting: run STEP 3C (Moving MNIST)"
    f = MM_ROOT / "runs" / digest(mm_config(job))[:16]
    if not (f / "config.json").exists():
        return None, "not started"
    st = ("failed" if (f / "FAILED.json").exists() else
          "evaluated" if (f / "EVALUATED.json").exists() else "trained" if (f / "DONE.json").exists()
          else "in progress" if (f / "last.pt").exists() or (f / "last.pt.previous").exists() else "started")
    return f, st


def _mm_validate(model, loss_kind):
    model.eval()
    acc = dict(loss=0.0, m1=0.0, p1=0.0, mh=0.0, ph=0.0, cp=0.0, ct=0.0, n=0)
    with torch.inference_mode():
        for s0 in range(0, MM_VAL_SEQ, 64):
            b = mm_batch(MM_DATA, "validation", 0, 0, range(s0, min(MM_VAL_SEQ, s0 + 64))).to(DEVICE)
            x, y = b[:, :10], b[:, 10:]
            p = model(x, 10)
            acc["loss"] += float(_per_sample_objective(p, y, loss_kind, x[:, -1]).sum())
            p, a = p.float().clamp(0, 1), x[:, -1]
            acc["m1"] += float((p[:, 0] - y[:, 0]).square().mean((1, 2, 3)).sum())
            acc["p1"] += float((a - y[:, 0]).square().mean((1, 2, 3)).sum())
            acc["mh"] += float((p[:, -1] - y[:, -1]).square().mean((1, 2, 3)).sum())
            acc["ph"] += float((a - y[:, -1]).square().mean((1, 2, 3)).sum())
            acc["cp"] += float((p[:, -1] - a).abs().mean((1, 2, 3)).sum())
            acc["ct"] += float((y[:, -1] - a).abs().mean((1, 2, 3)).sum())
            acc["n"] += len(b)
    div = lambda u, v: float(u / v) if v > 0 else float("nan")
    return acc["loss"] / acc["n"], {"val_skill_t1": 1 - div(acc["m1"], acc["p1"]), "val_skill_th": 1 - div(acc["mh"], acc["ph"]),
                                    "val_change_ratio": div(acc["cp"], acc["ct"])}


def mm_train(job, deadline):
    cfg = mm_config(job)
    folder = MM_ROOT / "runs" / digest(cfg)[:16]
    folder.mkdir(parents=True, exist_ok=True)
    atomic_json(folder / "config.json", cfg)
    if (folder / "DONE.json").exists():
        return folder
    _engine.seed_all(cfg["seed"])
    if FAST_CUDNN:                     # same cuDNN setting as the CLEVRER / KTH runs (seed_all sets deterministic)
        torch.backends.cudnn.benchmark, torch.backends.cudnn.deterministic = True, False
    ident = {"software": _engine.software_identity(), "source": _engine.source_identity()}
    if not (folder / "software.json").exists():
        atomic_json(folder / "software.json", ident)
    elif json.loads((folder / "software.json").read_text()) != ident:
        atomic_json(folder / f"software_change_{time.time_ns()}.json", ident | {"note": "resumed after a software change; report in methods"})
    model = mm_model(cfg["name"]).to(DEVICE)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg["lr"], weight_decay=cfg["weight_decay"])
    amp = cfg["precision"] == "fp16" and torch.cuda.is_available()
    scaler = torch.amp.GradScaler("cuda", enabled=amp)
    per_epoch = MM_TRAIN_SEQ // MM_BATCH
    epoch, next_batch, updates, best, history, val_est = 0, 0, 0, float("inf"), [], None
    latest = folder / "last.pt"
    if latest.exists() or latest.with_name("last.pt.previous").exists():
        try:
            state = torch.load(latest, map_location="cpu", weights_only=False)
        except Exception:
            state = torch.load(str(latest) + ".previous", map_location="cpu", weights_only=False)
        if state["config"] != cfg:
            raise RuntimeError("Moving MNIST resume configuration mismatch")
        model.load_state_dict(state["model"])
        opt.load_state_dict(state["optimizer"])
        if "scaler" in state:
            scaler.load_state_dict(state["scaler"])
        epoch, next_batch, updates = state["epoch"], state["next_batch"], state["updates"]
        best, history, val_est = state["best"], state["history"], state.get("val_seconds")
        _engine.restore_rng(state["rng"])
        del state

    def ckpt():
        return {"config": cfg, "model": model.state_dict(), "optimizer": opt.state_dict(), "scaler": scaler.state_dict(),
                "rng": _engine.rng_state(),
                "epoch": epoch, "next_batch": next_batch, "updates": updates, "best": best, "history": history,
                "val_seconds": val_est}

    def progress():
        atomic_json(folder / "progress.json", {"epoch": epoch, "epochs": cfg["epochs"], "next_batch": next_batch,
                                               "updates": updates, "updates_per_epoch": per_epoch,
                                               "validation_seconds": val_est, "saved_at": time.time()})

    started, last_saved, n_sess = time.monotonic(), time.monotonic(), 0
    amp_skipped = 0
    best_dirty = False                 # best.pt staged locally, not yet on Drive (published with last.pt)

    def publish_best():
        nonlocal best_dirty
        if best_dirty:
            _save_checkpoint_async(folder / "best.pt")
            best_dirty = False
    pool = ThreadPoolExecutor(2)
    print(f"▶ Moving MNIST {cfg['name']} seed {cfg['seed']} | resuming at epoch {epoch+1}/{cfg['epochs']}, batch {next_batch}",
          flush=True)
    try:
        while epoch < cfg["epochs"]:
            order = np.random.default_rng(cfg["seed"] + epoch).permutation(MM_TRAIN_SEQ)
            get = lambda bi, e=epoch, o=order: mm_batch(MM_DATA, "train", cfg["seed"], e, o[bi * MM_BATCH:(bi + 1) * MM_BATCH])
            futs = {bi: pool.submit(get, bi) for bi in range(next_batch, min(per_epoch, next_batch + 2))}
            model.train()
            bar = tqdm(total=per_epoch, initial=next_batch, desc=f"  mmnist {cfg['name']} s{cfg['seed']} epoch {epoch+1}",
                       unit="upd", dynamic_ncols=True, leave=False)
            for bi in range(next_batch, per_epoch):
                b = (futs.pop(bi, None) or pool.submit(get, bi)).result()
                if bi + 2 < per_epoch:
                    futs[bi + 2] = pool.submit(get, bi + 2)
                b = b.to(DEVICE, non_blocking=True)
                x, y = b[:, :10], b[:, 10:]
                opt.zero_grad(set_to_none=True)
                with torch.autocast("cuda", dtype=torch.float16, enabled=amp):
                    pred = model(x, 10)
                loss = _per_sample_objective(pred.float(), y, cfg["loss"], x[:, -1]).mean()   # loss in fp32
                if not torch.isfinite(loss):
                    raise FloatingPointError("Nonfinite Moving MNIST training loss")
                scaler.scale(loss).backward()
                scaler.unscale_(opt)
                gnorm = torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0, error_if_nonfinite=not scaler.is_enabled())
                scaler.step(opt)
                scaler.update()
                if scaler.is_enabled() and not math.isfinite(float(gnorm)):     # AMP overflow: step skipped (normal)
                    amp_skipped += 1
                    if amp_skipped >= globals().get("AMP_MAX_SKIPPED", 100):
                        raise FloatingPointError(f"AMP: {amp_skipped} consecutive non-finite gradient steps; diverged")
                else:
                    amp_skipped = 0
                updates, next_batch, n_sess = updates + 1, bi + 1, n_sess + 1
                bar.update(1)
                now = time.monotonic()
                late = deadline is not None and now > deadline
                if now - last_saved >= MM_CHECKPOINT_SECONDS or late:
                    publish_best()
                    _save_checkpoint_async(latest, ckpt())
                    progress()
                    last_saved = time.monotonic()
                if late:
                    bar.close()
                    print("⏸ Session deadline reached; Moving MNIST progress saved.", flush=True)
                    return folder
            bar.close()
            if deadline is not None and val_est and time.monotonic() + val_est > deadline:
                publish_best()
                _save_checkpoint_async(latest, ckpt())
                progress()
                print("⏸ Validation would not fit in this session; progress saved.", flush=True)
                return folder
            t0 = time.monotonic()
            score, diag = _mm_validate(model, cfg["loss"])
            val_est = time.monotonic() - t0
            if not math.isfinite(score):
                raise FloatingPointError("Nonfinite Moving MNIST validation loss")
            history.append({"epoch": epoch + 1, "validation_loss": score, "updates": updates, **diag})
            improved = score < best
            if improved:
                best = score
                _stage_local(folder / "best.pt", {"config": cfg, "epoch": epoch + 1, "model": model.state_dict()})
                best_dirty = True
            epoch, next_batch = epoch + 1, 0
            # Drive: best.pt + last.pt are published TOGETHER (one timeline) at most every MM_CHECKPOINT_SECONDS and at
            # the end - fewer Drive writes (each replaced file goes to the writer's Trash); <=30 min redone after a crash
            if epoch == cfg["epochs"] or time.monotonic() - last_saved >= MM_CHECKPOINT_SECONDS:
                publish_best()
                _save_checkpoint_async(latest, ckpt())
                last_saved = time.monotonic()
                progress()
                atomic_csv(folder / "history.csv", pd.DataFrame(history))
            print(f"  ✓ mmnist epoch {epoch}/{cfg['epochs']} | val loss {score:.5f} | skill t+1 {diag['val_skill_t1']:+.3f}"
                  f" | skill t+10 {diag['val_skill_th']:+.3f} | change ratio {diag['val_change_ratio']:.2f}", flush=True)
        publish_best()                 # the final best.pt must be on Drive before DONE
        _wait_uploads()
        best_row = min(history, key=lambda h: h["validation_loss"])
        atomic_json(folder / "DONE.json", {"best_validation_loss": best, "best_epoch_diagnostics": best_row, **flags(best_row)})
    finally:
        pool.shutdown(wait=False, cancel_futures=True)
        _wait_uploads()
        if n_sess >= 20:
            record_speed("mmnist", cfg["name"], "observed", s_per_update=(time.monotonic() - started) / n_sess,
                         validation_seconds=val_est)
        for _tmp in LOCAL.glob(f"{folder.name}-*.local"):
            _tmp.unlink(missing_ok=True)
        del model, opt
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    return folder


def mm_evaluate(folder, deadline, persistence=False):
    """Standard test file, saved in parts of MM_TEST_CHUNK sequences; returns the CSV path or None if paused."""
    out_dir = MM_ROOT / "persistence" if persistence else folder
    out_dir.mkdir(parents=True, exist_ok=True)
    final = out_dir / "test_per_sequence.csv"
    if final.exists():
        return final
    model = None
    if not persistence:
        cfg = json.loads((folder / "config.json").read_text())
        model = mm_model(cfg["name"]).to(DEVICE)
        model.load_state_dict(torch.load(folder / "best.pt", map_location="cpu", weights_only=True)["model"])
        model.eval()
    n = len(MM_DATA["test"])
    t0, done_now = time.monotonic(), 0
    try:
        for k in range(math.ceil(n / MM_TEST_CHUNK)):
            part = out_dir / f"test_part_{k:02d}.csv"
            if part.exists():
                continue
            if deadline is not None and time.monotonic() > deadline:
                print("⏸ Moving MNIST evaluation paused at the session deadline (finished parts saved).", flush=True)
                return None
            rows = []
            with torch.inference_mode():
                for s0 in range(k * MM_TEST_CHUNK, min(n, (k + 1) * MM_TEST_CHUNK), 100):
                    idx = list(range(s0, min(n, s0 + 100, (k + 1) * MM_TEST_CHUNK)))
                    b = mm_batch(MM_DATA, "test", 0, 0, idx).to(DEVICE)
                    x, y = b[:, :10], b[:, 10:]
                    p = x[:, -1:].expand(-1, 10, -1, -1, -1) if model is None else model(x, 10)
                    m = {k_: v_.detach().cpu().numpy() for k_, v_ in mm_metrics(p, y, x[:, -1]).items()}
                    for j, i in enumerate(idx):
                        r = {"seq": i, **{c: float(m[c][j]) for c in ("mse", "mae", "ssim", "psnr", "mse_copy")}}
                        r.update({f"mse_t{h+1}": float(m["mse_by_frame"][j, h]) for h in range(10)})
                        r.update({f"copy_t{h+1}": float(m["copy_by_frame"][j, h]) for h in range(10)})
                        rows.append(r)
                    done_now += len(idx)
            atomic_csv(part, pd.DataFrame(rows))
        parts = sorted(out_dir.glob("test_part_*.csv"))
        df = pd.concat([pd.read_csv(p) for p in parts], ignore_index=True)
        if sorted(df.seq) != list(range(n)):
            raise RuntimeError("Incomplete Moving MNIST evaluation")
        atomic_csv(final, df)
        if model is not None and done_now >= 500:
            record_speed("mmnist", cfg["name"], "observed", eval_s_per_window=(time.monotonic() - t0) / done_now)
        return final
    finally:
        del model
        gc.collect()


def mm_run_job(job, train_deadline, eval_deadline):
    """Train (resume) and evaluate one Moving MNIST job. Returns 'evaluated' or 'paused'."""
    folder = mm_train(job, train_deadline)
    atomic_json(ROOT / "current_run.json", {"run_id": folder.name, "dataset": "mmnist"})
    if not (folder / "DONE.json").exists():
        return "paused"
    a = mm_evaluate(folder, eval_deadline)
    b = mm_evaluate(folder, eval_deadline, persistence=True) if a is not None else None
    if a is None or b is None:
        return "paused"
    atomic_json(folder / "EVALUATED.json", {"metrics": str(a), "persistence": str(b)})
    print(f"  ✓ Moving MNIST {job['name']} seed {job['seed']} evaluated on the standard test file", flush=True)
    if globals().get("AUTO_CLEAN_FINISHED", True):      # resume-only files (best.pt is weights-only and kept)
        for name in ("last.pt", "last.pt.previous", "best.pt.previous"):
            (folder / name).unlink(missing_ok=True)
        for p_ in folder.glob("test_part_*.csv"):
            p_.unlink(missing_ok=True)
    return "evaluated"


def mm_estimate(job, table=None):
    sp = speed_lookup("mmnist", job["name"], table)
    if not sp or "s_per_update" not in sp:
        return None
    f, st = mm_find_run(job)
    if st in ("evaluated", "failed"):
        return {"train": 0.0, "eval": 0.0, "validation": 0.0}
    per_epoch = MM_TRAIN_SEQ // MM_BATCH
    done = 0
    if f is not None and (f / "progress.json").exists():
        done = json.loads((f / "progress.json").read_text()).get("updates", 0)
    ev = sp.get("eval_s_per_window", sp["s_per_update"] / MM_BATCH)
    val = sp.get("validation_seconds") or MM_VAL_SEQ * ev
    left = 0 if st == "trained" else MM_EPOCHS * per_epoch - done
    return {"train": left * sp["s_per_update"] + (left / per_epoch) * val, "eval": len(MM_DATA["test"]) * ev,
            "validation": val}

MM_DATA = None
