# ----------------------------- SETTINGS (edit here) -----------------------------
PATCH_ID = "nexvip_fast_runtime_v7"
DEVICE = "cuda"
# Samples per forward/backward pass. Effective batch stays 32 (gradients are accumulated).
# On CUDA out-of-memory the update is retried with half the microbatch automatically.
MICROBATCH = {"nex": 32, "predrnnpp": 16, "phydnet": 16, "simvpv2_gsta": 16, "tau": 16}
# These two use BatchNorm2d (OpenSTL GASubBlock/TAUSubBlock). Batching changes their batch
# statistics, so a run that ALREADY started with another microbatch keeps its old value.
BATCHNORM_MODELS = {"simvpv2_gsta", "tau"}
EVAL_BATCH = 16            # windows per forward pass in validation / evaluation
PREFETCH_BATCHES = 4 if (os.cpu_count() or 2) >= 4 else 2   # training batches prepared ahead in background threads
FULL_BATCH_GPU_GIB = 20    # on GPUs with ≥ this memory (L4 24 GB, A100) every model uses the full batch of 32
                           # (no gradient accumulation); smaller GPUs keep MICROBATCH below. OOM still halves it.
CHECKPOINT_SECONDS = 1800  # Drive checkpoint every 30 min (best.pt + last.pt together; local copies every epoch).
                           # Each replaced Drive file goes to the writer's Trash and counts against its quota, so
                           # fewer uploads = less Trash. ≤30 min of training is redone after a disconnect.
AMP_MAX_SKIPPED = 100      # AMP: this many consecutive overflow-skipped steps (loss scale → ~0) = diverged
FAST_CUDNN = True          # False restores deterministic cuDNN (slower)
ALLOW_SOFTWARE_CHANGE_RESUME = True  # resume a matching run after a Colab package update (logged)
MOTION_THRESHOLD = 0.04    # a pixel "changes" if any RGB channel differs from the last input by > 0.04 (≈10/255)
COLLAPSE_RATIO = 0.10      # change ratio below this ⇒ run flagged as collapsed to copy-last-frame
DEFAULT_LR = 2e-4          # learning rate of every existing run (part of the run identity)
