for _k, _v in MICROBATCH.items():
    if not isinstance(_v, int) or not 1 <= _v <= 32:
        raise ValueError(f"MICROBATCH[{_k}] must be an integer 1..32")


def _resolve_run(cfg):
    exact = ROOT / "runs" / digest(cfg)[:16]
    if (exact / "config.json").exists():
        existing = json.loads((exact / "config.json").read_text())
        if existing != cfg:
            raise RuntimeError("Run-id collision/configuration mismatch; no files overwritten")
        return exact, existing
    scientific = {k: v for k, v in cfg.items() if k not in ("source", "software")}
    matches = []
    for p in (ROOT / "runs").glob("*/config.json"):
        old = json.loads(p.read_text())
        if {k: v for k, v in old.items() if k not in ("source", "software")} == scientific:
            matches.append((p.parent, old))
    if len(matches) > 1:
        raise RuntimeError("Several scientifically identical runs exist: "
                           + ", ".join(str(p) for p, _ in matches) + ". Resolve manually.")
    if matches:
        folder, old = matches[0]
        if not ALLOW_SOFTWARE_CHANGE_RESUME:
            raise RuntimeError("Matching run has a different software/source identity: " + str(folder))
        changed = {k: {"recorded": old.get(k), "current": cfg.get(k)}
                   for k in ("software", "source") if old.get(k) != cfg.get(k)}
        log = folder / f"software_change_{digest(changed)[:12]}.json"
        if not log.exists():
            atomic_json(log, {"patch_id": PATCH_ID, "changed": changed, "first_seen_ns": time.time_ns(),
                              "note": "Run continued under a different environment; report in methods."})
            print("NOTE: using", folder.name, "after an environment change (logged in the run folder).")
        return folder, old
    return exact, cfg


def _microbatch_for(name, folder):
    key = "nex" if name.startswith("nex_") else name
    mb = int(MICROBATCH.get(key, 1))
    if (name not in BATCHNORM_MODELS and torch.cuda.is_available()
            and torch.cuda.get_device_properties(0).total_memory >= FULL_BATCH_GPU_GIB * 2**30):
        mb = 32   # large GPU: whole batch at once (gradient accumulation is equivalent for models WITHOUT BatchNorm;
                  # BatchNorm models keep MICROBATCH on every GPU so all their seeds see the same batch statistics)
    if name in BATCHNORM_MODELS and ((folder / "last.pt").exists() or (folder / "last.pt.previous").exists()):
        prior = []
        for p in sorted(folder.glob("runtime_patch_*.json")):
            v = json.loads(p.read_text()).get("requested_microbatch")
            if v is not None:
                prior.append(int(v))
        ooms = [int(json.loads(p.read_text())["actual_microbatch"]) for p in folder.glob("microbatch_oom_*.json")]
        if ooms:                        # the run actually trained with the reduced microbatch after an OOM
            prior = [min(ooms)]
        if prior and prior[0] != mb:
            print(f"{name}: run already started with microbatch {prior[0]} (BatchNorm); keeping it.")
            mb = prior[0]
    return mb


def _record_execution(folder, cfg, microbatch):
    atomic_json(folder / f"runtime_patch_{time.time_ns()}.json", {
        "patch_id": PATCH_ID, "requested_microbatch": microbatch, "effective_batch": 32,
        "checkpoint_seconds": CHECKPOINT_SECONDS, "cudnn_benchmark": FAST_CUDNN,
        "eval_batch": EVAL_BATCH, "prefetch_batches": PREFETCH_BATCHES,
        "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu",
        "torch": torch.__version__, "source_archive": str(_PATCH_ARCHIVE),
        "note": "Original config retained as experiment identity; runtime execution recorded separately."})


def aux_loss_type(kind):
    """'motion' (temporal-change, plan A), 'tdiff' (temporal-difference, plan B) or None."""
    return "motion" if "_motion@" in kind else "tdiff" if "_tdiff@" in kind else None


def parse_loss(kind):
    """'l1_ssim_motion@0.5' / 'l1_ssim_tdiff@2' -> ('l1_ssim', w); plain kinds -> (kind, 0.0)."""
    aux = aux_loss_type(kind)
    if aux:
        base, w = kind.split(f"_{aux}@")
        w = float(w)
        if base not in ("l1_ssim", "l1", "mse") or not (0 < w <= 100):
            raise ValueError(f"Unsupported {aux} loss: " + kind)
        return base, w
    if kind not in ("l1_ssim", "l1", "ssim", "mse"):
        raise ValueError("Unknown loss_kind: " + kind)
    return kind, 0.0


def motion_mask(target, anchor):
    """1 where the target differs from the last input frame (B,T,1,H,W)."""
    return ((target.float() - anchor.float()[:, None]).abs().amax(2, keepdim=True) > MOTION_THRESHOLD).float()


def _per_sample_objective(pred, target, kind="l1_ssim", anchor=None):
    """Same loss as engine.objective, computed for every sample in one call.
    For one sample it equals engine.objective(pred[j:j+1], target[j:j+1], kind).
    Motion kinds (plan A) add w × mean |pred − target| over changing pixels.
    Temporal-difference kinds (plan B) add w × mean |(pred_t − pred_t−1) − (target_t − target_t−1)|, with the
    last input frame as frame t−1 for the first prediction: a static (copied) forecast pays wherever things move.
    Both need anchor = last input frame."""
    aux = aux_loss_type(kind)
    kind, weight = parse_loss(kind)
    base = _base_objective(pred, target, kind)
    if weight == 0:
        return base
    if anchor is None:
        raise ValueError("Motion / temporal-difference loss needs the last input frame")
    if aux == "tdiff":
        p, t, a = pred.float(), target.float(), anchor.float()[:, None]
        dp = p - torch.cat((a, p[:, :-1]), 1)
        dt = t - torch.cat((a, t[:, :-1]), 1)
        return base + weight * (dp - dt).abs().flatten(1).mean(1)
    m = motion_mask(target, anchor)
    err = (pred.float() - target.float()).abs().mean(2, keepdim=True)
    motion = (m * err).flatten(1).sum(1) / m.flatten(1).sum(1).clamp_min(1.0)
    return base + weight * motion


def _base_objective(pred, target, kind):
    p, t = pred.float(), target.float()
    b = p.shape[0]
    if kind == "mse":
        return (p - t).square().flatten(1).mean(1)
    l1 = (p - t).abs().flatten(1).mean(1)
    if kind == "l1":
        return l1
    s = _ssim_fn(p.flatten(0, 1), t.flatten(0, 1), data_range=1.0, reduction="none").view(b, -1).mean(1)
    if kind == "ssim":
        return 0.5 * (1 - s)
    return l1 + 0.5 * (1 - s)


def _to_device(t, device):
    """Host batch → device; uint8 frames are converted to [0, 1] float32 ON the device (identical to CPU x/255)."""
    t = t.to(device, non_blocking=True)
    return t.float().div_(255) if t.dtype == torch.uint8 else t


def _load_batch(ds, indices):
    ds.as_uint8 = True                 # raw frames from the cache; converted on the GPU (_to_device)
    xs, ys = [], []
    for i in indices:
        x, y, _, _ = ds[int(i)]
        xs.append(x)
        ys.append(y)
    x, y = torch.stack(xs), torch.stack(ys)
    if torch.cuda.is_available():
        x, y = x.pin_memory(), y.pin_memory()
    return x, y


class _Prefetcher:
    """Loads upcoming training batches in background threads, in the original order.
    Window starts depend only on (seed, epoch, video, window), so threading does not change data."""
    def __init__(self, ds, batches, start):
        self.ds, self.batches = ds, batches
        self.pool = ThreadPoolExecutor(max(1, PREFETCH_BATCHES))
        self.futures = {}
        for bi in range(start, min(len(batches), start + PREFETCH_BATCHES)):
            self.futures[bi] = self.pool.submit(_load_batch, ds, batches[bi])

    def get(self, bi):
        fut = self.futures.pop(bi, None) or self.pool.submit(_load_batch, self.ds, self.batches[bi])
        nxt = bi + PREFETCH_BATCHES
        if nxt < len(self.batches) and nxt not in self.futures:
            self.futures[nxt] = self.pool.submit(_load_batch, self.ds, self.batches[nxt])
        return fut.result()

    def close(self):
        self.pool.shutdown(wait=False, cancel_futures=True)


_UPLOADER = ThreadPoolExecutor(1)
_PENDING_UPLOADS = []


def _wait_uploads():
    while _PENDING_UPLOADS:
        _PENDING_UPLOADS.pop(0).result()


def _stage_local(path, state):
    """Save a checkpoint to the local disk only (fast, no Drive write); published later by _save_checkpoint_async."""
    path = Path(path)
    temp = LOCAL / f"{path.parent.name}-{path.name}.local"
    torch.save(state, temp)
    return temp


def _save_checkpoint_async(path, state=None):
    """Write locally now (state=None: publish the already staged local copy); copy + verify + publish on Drive in
    the background. The previous valid Drive checkpoint is kept until the new one is verified.
    Transient Drive errors are retried 3x (30 s apart) before they are raised."""
    _wait_uploads()
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = LOCAL / f"{path.parent.name}-{path.name}.local"
    if state is not None:
        torch.save(state, temp)
    elif not temp.exists():
        return

    def upload():
        for attempt in range(3):
            try:
                return _upload_once()
            except OSError:
                if attempt == 2:
                    raise
                time.sleep(30)

    def _upload_once():
        target = path.with_name(path.name + ".partial")
        target.unlink(missing_ok=True)
        shutil.copy2(temp, target)
        if sha(temp) != sha(target):
            raise IOError("Checkpoint transfer verification failed: " + str(path))
        if path.exists():
            prev = path.with_name(path.name + ".previous")
            # Delete the old fallback explicitly, then RENAME (never overwrite). Overwriting a file on the Drive mount
            # detaches the replaced file; in a folder owned by another account it then sits, unseen, in the writer's
            # My Drive root and fills that account's 15 GB. An explicit delete goes to the writer's Trash instead.
            prev.unlink(missing_ok=True)
            os.replace(path, prev)
        os.replace(target, path)

    _PENDING_UPLOADS.append(_UPLOADER.submit(upload))


def _backward_attempt(model, scaler, bx, by, horizon, precision, loss_kind, microbatch):
    total = bx.shape[0]
    losses = []
    for s in range(0, total, microbatch):
        x = _to_device(bx[s:s + microbatch], DEVICE)
        y = _to_device(by[s:s + microbatch], DEVICE)
        with torch.autocast("cuda", dtype=torch.float16, enabled=precision == "fp16"):
            pred = model(x, horizon)
        # loss (incl. SSIM's E[x²]−μ² terms) in FP32, outside autocast: FP16 cancellation is as large as SSIM's C2
        loss = _per_sample_objective(pred.float(), y.float(), loss_kind, x[:, -1].float()).sum() / total
        losses.append(loss.detach())
        scaler.scale(loss).backward()
    value = float(torch.stack(losses).sum())
    if not math.isfinite(value):
        raise FloatingPointError("Nonfinite training loss; optimizer not advanced")
    return value


def _backward_update(model, optimizer, scaler, bx, by, horizon, precision, loss_kind, microbatch, folder):
    rng = _engine.rng_state()
    while True:
        optimizer.zero_grad(set_to_none=True)
        oom = False
        try:
            value = _backward_attempt(model, scaler, bx, by, horizon, precision, loss_kind, microbatch)
        except torch.cuda.OutOfMemoryError:
            if microbatch <= 1:
                raise
            oom = True
        if not oom:
            return microbatch, value
        optimizer.zero_grad(set_to_none=True)
        gc.collect()
        torch.cuda.empty_cache()
        _engine.restore_rng(rng)
        microbatch = max(1, microbatch // 2)
        atomic_json(folder / f"microbatch_oom_{time.time_ns()}.json",
                    {"patch_id": PATCH_ID, "actual_microbatch": microbatch})
        print("Out of GPU memory: retrying the same update with microbatch", microbatch, flush=True)


def _validate(model, cache, manifest, horizon, seed, initial_only, loss_kind, split="validation"):
    """Returns (validation objective, diagnostics). Diagnostics use the same forecasts:
    skill_h = 1 − ΣMSE(model) / ΣMSE(persistence) at t+1 and t+horizon (>0 ⇒ better than copying),
    change_ratio = Σ|pred − last input| / Σ|target − last input| at t+horizon (≈0 ⇒ copies last frame)."""
    vd = _engine.Windows(cache, manifest[split], horizon, 1, 0, seed, False, initial_only)
    vals, step, s = [], EVAL_BATCH, 0
    acc = dict(m1=0.0, p1=0.0, mh=0.0, ph=0.0, cp=0.0, ct=0.0, n=0)
    bar = tqdm(total=len(vd), desc="  validating", unit="video", leave=False, dynamic_ncols=True)
    device = DEVICE
    with torch.inference_mode():
        while s < len(vd):
            idx = range(s, min(len(vd), s + step))
            try:
                x, y = _load_batch(vd, idx)
                x, y = _to_device(x, device), _to_device(y, device)
                p = model(x, horizon)
                vals.extend(_per_sample_objective(p, y, loss_kind, x[:, -1]).tolist())
                p, y, a = p.float().clamp(0, 1), y.float(), x[:, -1].float()
                acc["m1"] += float((p[:, 0] - y[:, 0]).square().mean((1, 2, 3)).sum())
                acc["p1"] += float((a - y[:, 0]).square().mean((1, 2, 3)).sum())
                acc["mh"] += float((p[:, -1] - y[:, -1]).square().mean((1, 2, 3)).sum())
                acc["ph"] += float((a - y[:, -1]).square().mean((1, 2, 3)).sum())
                acc["cp"] += float((p[:, -1] - a).abs().mean((1, 2, 3)).sum())
                acc["ct"] += float((y[:, -1] - a).abs().mean((1, 2, 3)).sum())
                acc["n"] += len(idx)
                s += len(idx)
                bar.update(len(idx))
            except torch.cuda.OutOfMemoryError:
                if step == 1:
                    raise
                step = max(1, step // 2)
                gc.collect()
                torch.cuda.empty_cache()
    bar.close()
    div = lambda a, b: float(a / b) if b > 0 else float("nan")
    diag = {"val_mse_t1": div(acc["m1"], acc["n"]), "val_persistence_mse_t1": div(acc["p1"], acc["n"]),
            "val_skill_t1": 1 - div(acc["m1"], acc["p1"]),
            f"val_mse_t{horizon}": div(acc["mh"], acc["n"]),
            f"val_persistence_mse_t{horizon}": div(acc["ph"], acc["n"]),
            "val_skill_th": 1 - div(acc["mh"], acc["ph"]),
            "val_change_ratio": div(acc["cp"], acc["ct"])}
    return float(np.mean(vals)), diag


def flags(diag):
    """Collapse detector and sanity gate from validation diagnostics."""
    cr, s1 = diag.get("val_change_ratio", float("nan")), diag.get("val_skill_t1", float("nan"))
    return {"collapsed": bool(math.isfinite(cr) and cr < COLLAPSE_RATIO),
            "sanity_gate_pass": bool(math.isfinite(s1) and s1 > 0)}


def validation_diagnostics(model, cache, manifest, seed=2024, horizon=10):
    """For runs trained before v6 (no diagnostics in history): same measurement on validation videos."""
    model.eval()
    _, diag = _validate(model, cache, manifest, horizon, seed, False, "l1_ssim")
    diag.update(flags(diag))
    return diag


# ----------------------------- speed table (free-tier session planning) -----------------------------
# Seconds per training update / evaluation window for each (dataset, architecture) on this GPU type.
# Filled by STEP 4B (short timing run) and refined automatically from every real training/evaluation.
GPU_NAME = torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu"
SPEED_FILE = ROOT / "analysis" / ("speed_" + re.sub(r"[^A-Za-z0-9]+", "_", GPU_NAME).strip("_")
                                  + "_" + globals().get("PRECISION_ALL", "fp32") + ".json")   # timings per GPU and precision


def load_speed():
    try:
        return json.loads(SPEED_FILE.read_text())
    except (OSError, ValueError):
        return {"gpu": GPU_NAME, "entries": {}}


def record_speed(dataset, name, source, **values):
    """source: 'speedcheck' (STEP 4B) or 'observed' (real work; smoothed, and preferred over speedcheck)."""
    try:
        table = load_speed()
        e = table["entries"].setdefault(f"{dataset}|{name}", {})
        for k, v in values.items():
            if v is None or not math.isfinite(float(v)) or v <= 0:
                continue
            if source == "observed" and e.get(k + "_source") == "observed":
                v = 0.5 * e[k] + 0.5 * float(v)
            elif source == "speedcheck" and e.get(k + "_source") == "observed":
                continue
            e[k], e[k + "_source"] = float(v), source
        e["updated"] = time.time()
        SPEED_FILE.parent.mkdir(parents=True, exist_ok=True)
        atomic_json(SPEED_FILE, table)
    except Exception as err:   # planning data only: never interrupt training for it
        print("  (speed table not updated:", err, ")")


def speed_lookup(dataset, name, table=None):
    entries = (table or load_speed())["entries"]
    e = entries.get(f"{dataset}|{name}")
    if e is None and name.startswith("nex_"):
        e = entries.get(f"{dataset}|nex_full")
    return e


def run_label(cfg):
    """Model id used in evaluation files: name, plus loss and learning rate when not the defaults."""
    lab = cfg["name"] if cfg["loss"] == "l1_ssim" else cfg["name"] + "__" + cfg["loss"]
    lr = cfg.get("lr", DEFAULT_LR)
    return lab if math.isclose(lr, DEFAULT_LR) else f"{lab}__lr{lr:g}"


def run_train(cache, manifest, name, seed=2024, epochs=20, precision="fp32", loss_kind="l1_ssim",
              max_hours=3, windows=3, initial_only=False, horizon=10, stop_after_updates=None, lr=DEFAULT_LR,
              deadline=None, val_seconds=None):
    """deadline: time.monotonic() value by which training must have paused and saved (session budget).
    val_seconds: expected duration of one end-of-epoch validation (pause instead of starting it too late)."""
    if DEVICE == "cuda" and not torch.cuda.is_available():
        raise RuntimeError("Select a Colab GPU runtime")
    parse_loss(loss_kind)
    if not (0 < float(lr) < 1):
        raise ValueError("lr must be in (0, 1)")
    cfg = {"name": name, "seed": seed, "epochs": epochs, "precision": precision, "loss": loss_kind,
           "lr": float(lr), "weight_decay": 1e-4, "effective_batch": 32, "microbatch": 1,
           "horizon": horizon, "windows": windows, "initial_only": initial_only,
           "split": manifest["id"], "cache": cache["id"],
           "software": _engine.software_identity(), "source": _engine.source_identity()}
    folder, cfg = _resolve_run(cfg)
    run_id = folder.name
    folder.mkdir(parents=True, exist_ok=True)
    atomic_json(folder / "config.json", cfg)
    if (folder / "DONE.json").exists():
        return folder
    microbatch = _microbatch_for(name, folder)
    _record_execution(folder, cfg, microbatch)
    _engine.seed_all(seed)
    if FAST_CUDNN:
        torch.backends.cudnn.benchmark = True
        torch.backends.cudnn.deterministic = False
    model = _engine.Predictor(name, DEVICE)
    optimizer = torch.optim.AdamW((p for p in model.parameters() if p.requires_grad),
                                  lr=cfg["lr"], weight_decay=cfg["weight_decay"])
    scaler = torch.amp.GradScaler("cuda", enabled=precision == "fp16")
    epoch, next_batch, updates, best, history = 0, 0, 0, float("inf"), []
    latest = folder / "last.pt"
    if latest.exists() or latest.with_name("last.pt.previous").exists():
        try:
            state = torch.load(latest, map_location="cpu", weights_only=False)
        except Exception:
            state = torch.load(str(latest) + ".previous", map_location="cpu", weights_only=False)
        if state["config"] != cfg:
            raise RuntimeError("Resume configuration mismatch")
        model.load_state_dict(state["model"])
        optimizer.load_state_dict(state["optimizer"])
        scaler.load_state_dict(state["scaler"])
        epoch, next_batch, updates = state["epoch"], state["next_batch"], state["updates"]
        best, history = state["best"], state["history"]
        _engine.restore_rng(state["rng"])
        del state

    def checkpoint():
        return {"execution": {"patch_id": PATCH_ID, "actual_microbatch": microbatch},
                "config": cfg, "model": model.state_dict(), "optimizer": optimizer.state_dict(),
                "scaler": scaler.state_dict(), "rng": _engine.rng_state(), "epoch": epoch,
                "next_batch": next_batch, "updates": updates, "best": best, "history": history}

    ds = _engine.Windows(cache, manifest["train"], horizon, windows, epoch, seed, True, initial_only)
    x, y, _, _ = ds[0]
    model.eval()
    probe = model(x[None].to(DEVICE), horizon)
    if not probe.requires_grad:
        raise RuntimeError("Adapter detached the forecast")
    if probe.shape != y[None].shape:
        raise RuntimeError("Forecast shape mismatch")
    del probe
    per_epoch = math.ceil(len(ds) / 32)
    started = time.monotonic()
    last_saved, session_updates, prefetch, bar = started, 0, None, None
    amp_skipped = 0
    best_dirty = False
    val_est, val_measured = val_seconds, None

    def write_progress():
        rate_now = (time.monotonic() - started) / session_updates if session_updates else None
        atomic_json(folder / "progress.json", {
            "epoch": epoch, "epochs": epochs, "next_batch": next_batch, "updates": updates,
            "updates_per_epoch": per_epoch, "s_per_update_this_session": rate_now,
            "validation_seconds": val_est, "gpu": GPU_NAME, "saved_at": time.time()})
    print(f"▶ {name} | seed {seed} | split {manifest['id']} | resuming at epoch {epoch+1}/{epochs}, "
          f"batch {next_batch} | microbatch {microbatch}", flush=True)
    try:
        while epoch < epochs:
            ds = _engine.Windows(cache, manifest["train"], horizon, windows, epoch, seed, True, initial_only)
            order = np.random.default_rng(seed + epoch).permutation(len(ds)).tolist()
            batches = [order[i:i + 32] for i in range(0, len(order), 32)]
            model.train()
            prefetch = _Prefetcher(ds, batches, next_batch)
            bar = tqdm(total=len(batches), initial=next_batch, desc=f"  {name} s{seed} epoch {epoch+1}/{epochs}",
                       unit="upd", dynamic_ncols=True)
            for bi in range(next_batch, len(batches)):
                bx, by = prefetch.get(bi)
                try:
                    microbatch, loss_value = _backward_update(model, optimizer, scaler, bx, by, horizon,
                                                              precision, loss_kind, microbatch, folder)
                except FloatingPointError:
                    if not scaler.is_enabled():
                        raise                   # FP32: a non-finite loss is divergence
                    # AMP: an FP16 overflow in the forward pass — skip this batch and halve the loss scale, exactly
                    # as GradScaler does for gradient overflow; counted toward AMP_MAX_SKIPPED (then FAILED).
                    optimizer.zero_grad(set_to_none=True)
                    scaler.update(scaler.get_scale() / 2)
                    amp_skipped += 1
                    if amp_skipped >= AMP_MAX_SKIPPED:
                        raise FloatingPointError(f"AMP: {amp_skipped} consecutive non-finite steps; training diverged")
                    next_batch = bi + 1
                    bar.update(1)
                    continue
                scaler.unscale_(optimizer)
                # With AMP, a non-finite gradient is a normal loss-scale overflow: GradScaler skips that step and lowers
                # the scale. Only a long run of skipped steps is divergence. Without AMP, any non-finite gradient is.
                gnorm = torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0, error_if_nonfinite=not scaler.is_enabled())
                scaler.step(optimizer)
                scaler.update()
                if scaler.is_enabled() and not math.isfinite(float(gnorm)):
                    amp_skipped += 1
                    if amp_skipped >= AMP_MAX_SKIPPED:
                        raise FloatingPointError(f"AMP: {amp_skipped} consecutive non-finite gradient steps "
                                                 f"(loss scale {scaler.get_scale():.3g}); training diverged")
                else:
                    amp_skipped = 0
                updates += 1
                session_updates += 1
                next_batch = bi + 1
                now = time.monotonic()
                rate = (now - started) / max(1, session_updates)
                remaining = (epochs - epoch - 1) * len(batches) + len(batches) - next_batch
                bar.update(1)
                bar.set_postfix(loss=f"{loss_value:.4f}", mb=microbatch, s_per_upd=f"{rate:.2f}",
                                job_ETA_h=f"{remaining*rate/3600:.1f}", refresh=False)
                out_of_time = now - started > max_hours * 3600 or (deadline is not None and now > deadline)
                stop_now = stop_after_updates is not None and session_updates >= stop_after_updates
                if now - last_saved >= CHECKPOINT_SECONDS or out_of_time or stop_now:
                    if best_dirty:                     # publish the newest best.pt BEFORE last.pt (consistent pair)
                        _save_checkpoint_async(folder / "best.pt")
                        best_dirty = False
                    _save_checkpoint_async(latest, checkpoint())
                    write_progress()
                    last_saved = time.monotonic()
                if out_of_time or stop_now:
                    bar.close()
                    print("⏸ Session deadline reached; progress saved. It resumes from here next session (Runtime → Run all).", flush=True)
                    return folder
            bar.close()
            bar = None
            prefetch.close()
            prefetch = None
            if deadline is not None and val_est and time.monotonic() + val_est > deadline:
                if best_dirty:
                    _save_checkpoint_async(folder / "best.pt")
                    best_dirty = False
                _save_checkpoint_async(latest, checkpoint())
                write_progress()
                print(f"⏸ Epoch {epoch+1} trained, but its validation (~{val_est/60:.0f} min) does not fit in this "
                      "session; progress saved. It runs first next session.", flush=True)
                return folder
            model.eval()
            t_val = time.monotonic()
            score, diag = _validate(model, cache, manifest, horizon, seed, initial_only, loss_kind)
            val_est = val_measured = time.monotonic() - t_val
            if not np.isfinite(score):
                raise FloatingPointError("Validation loss is nonfinite; completion not recorded")
            history.append({"epoch": epoch + 1, "validation_loss": score, "updates": updates, **diag})
            improved = score < best
            if improved:
                best = score
                _stage_local(folder / "best.pt", checkpoint())   # local now; published with the next Drive save
                best_dirty = True
            epoch += 1
            next_batch = 0
            if epoch < epochs and time.monotonic() - last_saved >= CHECKPOINT_SECONDS:
                if best_dirty:
                    _save_checkpoint_async(folder / "best.pt")
                    best_dirty = False
                _save_checkpoint_async(latest, checkpoint())
                last_saved = time.monotonic()
            write_progress()
            atomic_csv(folder / "history.csv", pd.DataFrame(history))
            fl = flags(diag)
            print(f"  ✓ epoch {epoch}/{epochs} | val loss {score:.5f}{' (best)' if improved else ''} | "
                  f"skill t+1 {diag['val_skill_t1']:+.3f} | skill t+{horizon} {diag['val_skill_th']:+.3f} | "
                  f"change ratio {diag['val_change_ratio']:.2f}"
                  + (" | ⚠ COLLAPSED (copies last frame)" if fl["collapsed"] else "")
                  + ("" if fl["sanity_gate_pass"] else " | ⚠ worse than copying at t+1"), flush=True)
        if best_dirty:                         # training finished: the final best.pt must be on Drive
            _save_checkpoint_async(folder / "best.pt")
            best_dirty = False
        _wait_uploads()
        best_row = min(history, key=lambda h: h["validation_loss"])
        summary = {"config_id": run_id, "epochs": epochs, "best_validation_loss": best}
        if "val_change_ratio" in best_row:   # best epoch was validated by v6 (else: measured later in STEP 8)
            clean = {k: (v if not isinstance(v, float) or math.isfinite(v) else None) for k, v in best_row.items()}
            summary.update({"best_epoch_diagnostics": clean, **flags(best_row)})
        atomic_json(folder / "DONE.json", summary)
    finally:
        if bar is not None:
            bar.close()
        if prefetch is not None:
            prefetch.close()
        _wait_uploads()
        if session_updates >= 20 or val_measured:
            record_speed(manifest["dataset"], name, "observed", validation_seconds=val_measured,
                         s_per_update=((time.monotonic() - started) / session_updates) if session_updates >= 20 else None)
        for _tmp in LOCAL.glob(f"{folder.name}-*.local"):   # local staging copies (Drive copy is verified)
            _tmp.unlink(missing_ok=True)
        del model, optimizer
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    return folder


# ----------------------------- batched held-out evaluation -----------------------------
def _complete_rows(rows, horizons):
    from collections import defaultdict
    groups = defaultdict(list)
    for row in rows:
        try:
            key = (str(row["video"]), int(row["start"]))
            h = int(row["horizon"])
            valid = all(math.isfinite(float(row[k])) for k in ("mse", "ssim", "lpips"))
        except (KeyError, TypeError, ValueError, OverflowError):
            continue
        groups[key].append((h, valid, row))
    complete, done = [], set()
    for key, group in groups.items():
        if len(group) == len(horizons) and {h for h, _, _ in group} == set(horizons) and all(v for _, v, _ in group):
            complete.extend(row for _, _, row in group)
            done.add(key)
    return complete, done


def _window_key(cache, manifest, windows, initial_only, i):
    rel = manifest["eval"][i // windows]
    max_start = cache["index"][rel]["n"] - 34
    if max_start < 0:
        raise ValueError("Too few cached frames: " + rel)
    start = 0 if initial_only else int(np.linspace(0, max_start, windows)[i % windows])
    return rel, start


def eval_spec(cache, manifest, model_id, seed, checkpoint_id, windows=3, initial_only=False, archive=None,
              limit=None):
    # Spec (and therefore the result folder) is identical to the original evaluate().
    return {"model": model_id, "seed": seed, "checkpoint": checkpoint_id, "split": manifest["id"],
            "cache": cache["id"], "windows": windows, "initial_only": initial_only,
            "horizons": [1, 5, 10, 20, 30], "pilot_limit": limit,
            "mask_archive": sha(archive) if archive else None,
            "software": _evaluation.software_identity(), "source": _evaluation.source_identity()}


LAST_EVAL = {}   # windows evaluated + seconds in the latest evaluate() call (speed table)


def evaluate(model, cache, manifest, model_id, seed, checkpoint_id, windows=3,
             initial_only=False, archive=None, limit=None, deadline=None):
    """deadline: time.monotonic() value; when reached, finished windows are saved and None is returned
    (the next call continues from them)."""
    LAST_EVAL.clear()
    spec = eval_spec(cache, manifest, model_id, seed, checkpoint_id, windows, initial_only, archive, limit)
    folder = ROOT / "evaluation" / digest(spec)[:16]
    folder.mkdir(parents=True, exist_ok=True)
    atomic_json(folder / "spec.json", spec)
    out = folder / "per_window.csv"
    rows = pd.read_csv(out).to_dict("records") if out.exists() and out.stat().st_size > 1 else []
    rows, done = _complete_rows(rows, spec["horizons"])
    ds = _evaluation.Windows(cache, manifest["eval"], 30, windows, 0, seed, False, initial_only)
    stop = len(ds) if limit is None else min(limit, len(ds))
    keys = [_window_key(cache, manifest, windows, initial_only, i) for i in range(stop)]
    expected = set(keys)
    if expected and expected.issubset(done):
        atomic_csv(out, pd.DataFrame(rows))
        atomic_json(folder / "DONE.json", {"complete_windows": len(expected), "pilot": limit is not None})
        print("Reusing verified complete evaluation:", folder.name)
        return out
    stale = folder / "DONE.json"
    if stale.exists():
        stale.unlink()
    masks = _evaluation.ProposalMasks(archive)
    met = _evaluation.Metrics(next(model.parameters(), torch.empty(0, device=DEVICE)).device)
    device = met.device
    model.eval()
    todo = [i for i in range(stop) if keys[i] not in done]
    hs = spec["horizons"]
    hidx = torch.tensor([h - 1 for h in hs])
    step, pos, last_print = EVAL_BATCH, 0, time.monotonic()
    t_eval, paused = time.monotonic(), False
    bar = tqdm(total=len(expected), initial=len(done & expected), desc=f"  evaluating {model_id} s{seed}",
               unit="window", dynamic_ncols=True)
    try:
        with torch.inference_mode():
            while pos < len(todo):
                if deadline is not None and time.monotonic() > deadline:
                    paused = True
                    break
                chunk = todo[pos:pos + step]
                try:
                    x, y = _load_batch(ds, chunk)
                    pred = model(_to_device(x, device), 30).clamp(0, 1)
                except torch.cuda.OutOfMemoryError:
                    if step == 1:
                        raise
                    step = max(1, step // 2)
                    gc.collect()
                    torch.cuda.empty_cache()
                    continue
                target = _to_device(y, device)
                if pred.shape != target.shape or not torch.isfinite(pred).all():
                    raise RuntimeError("Invalid evaluation forecast")
                for j, i in enumerate(chunk):
                    video, start = keys[i]
                    p5, t5 = pred[j, hidx.to(device)], target[j, hidx.to(device)]
                    mse = (p5 - t5).square().flatten(1).mean(1).tolist()
                    ssim = _ssim_fn(p5, t5, data_range=1.0, reduction="none").reshape(-1).tolist()
                    lp = met.lp(p5, t5).reshape(-1).detach().cpu().tolist()
                    met.lp.reset()
                    for k, h in enumerate(hs):
                        r = {"model": model_id, "seed": seed, "dataset": manifest["dataset"],
                             "split": manifest["id"], "video": video, "start": start, "horizon": h,
                             "pilot": limit is not None, "initial_only": initial_only,
                             "mse": float(mse[k]), "ssim": float(ssim[k]), "lpips": float(lp[k])}
                        r.update(met.regions(p5[k:k + 1], t5[k:k + 1], masks(video, start + 3 + h)))
                        rows.append(r)
                    done.add((video, start))
                pos += len(chunk)
                bar.update(len(chunk))
                if time.monotonic() - last_print > 300 or pos >= len(todo):   # partial save every 5 min (fewer Drive rewrites)
                    atomic_csv(out, pd.DataFrame(rows))
                    last_print = time.monotonic()
    finally:
        bar.close()
        if rows:
            atomic_csv(out, pd.DataFrame(rows))
        if masks.z is not None:
            masks.z.close()
        LAST_EVAL.update(windows=pos, seconds=time.monotonic() - t_eval)
    if paused:
        print(f"⏸ Evaluation paused at the session deadline: {len(done & expected)}/{len(expected)} windows saved; "
              "it continues from there next session.", flush=True)
        return None
    if not expected.issubset(done):
        raise RuntimeError("Incomplete evaluation")
    atomic_json(folder / "DONE.json", {"complete_windows": len(expected), "pilot": limit is not None})
    return out


