# Batched evaluation fix (found in v6 QA): for 30-frame rollouts SimVP-gSTA/TAU receive a sliced,
# non-contiguous context when the batch has >1 window, and OpenSTL's .view() then fails. Making the
# context contiguous changes no values (identical results to batch size 1).
import baseline_core as _bc
if not getattr(_bc.forecast_sequence, "_contiguous_fix", False):
    _orig_forecast_sequence = _bc.forecast_sequence

    def _forecast_sequence_contiguous(model, baseline, context):
        return _orig_forecast_sequence(model, baseline, context.contiguous())

    _forecast_sequence_contiguous._contiguous_fix = True
    _bc.forecast_sequence = _forecast_sequence_contiguous
