# ═════════════════════════════ v6 experiment queue (critical path first) ═════════════════════════════
# The old queue file (experiment_queue.json) is kept untouched. Finished runs with the same settings are
# reused automatically; nothing already trained is retrained.
COMPUTE_TIER = "critical"                 # "critical": reviewer-critical minimum (est. ~8–12 sessions, AMP)
                                          # "full": everything below (est. ~25–40 sessions). STEP 4B prints both
                                          # from speeds measured on your GPU; decide after session 1.
PRECISION_ALL = "fp16"                    # mixed precision (AMP) for EVERY new run and model (harmonized, ~3× faster
                                          # on a T4). "fp32" = full precision for all. Never mixed within one report.
MOTION_WEIGHTS = [0.5, 0.7, 0.85, 1.0, 2.0]   # plan A: temporal-change loss weights (chosen on VALIDATION only).
                                          # v7.1 added 0.7/0.85 after 0.5 collapsed and 1.0 overshot (disclosed;
                                          # the settings change is logged in analysis/selection_log.jsonl)
TDIFF_WEIGHTS = [0.5, 2.0]                # plan B: temporal-difference loss weights (run only if plan A fails)
REQUIRE_BEAT_COPY = True                  # gate 1: the chosen loss must also beat copy-last-frame on validation (t+10)
GATE_MARGIN = 0.01                        # gate 1: required margin in validation skill (vs plain loss and vs copy)
NEX_SEEDS = [2024, 2025, 2026, 2027, 2028]
SELECTION_SEED = 2024                     # seed used for every validation selection; the final NEX-ViP is ALSO run
REPORT_SEEDS = [2025, 2026, 2027, 2028, 2029]   # on these 5 seeds, which are reported (selection run kept separate)
BASELINE_SEEDS = [2024, 2025, 2026]
CLAIMED_ABLATIONS = ["nex_direct", "nex_aggregate", "nex_direct_skip"]   # residual design (reviewer point 12):
                                          # direct full-frame decoder · learned context anchor · direct + gated skip
KTH_WINDOWS = 15                          # training windows per KTH video per epoch (was 3 → ~540 updates)
ALLOW_MOTION_IF_NO_GAIN = False           # True only for debugging: continue even if gate 1 fails
IF_GATE1_FAILS = "paper_loss"             # v7.1. "paper_loss": if no auxiliary loss passes gate 1, NEX-ViP is trained
                                          # with its PUBLISHED objective (plain L1+SSIM) and every reviewer experiment
                                          # still runs; the sweep is reported as a negative result. "stop": old v7 behaviour
if IF_GATE1_FAILS not in ("paper_loss", "stop"):
    raise ValueError('IF_GATE1_FAILS must be "paper_loss" or "stop"')
PAPER_LOSS = "l1_ssim"
if COMPUTE_TIER == "critical":
    BASELINES = ["tau", "simvpv2_gsta", "phydnet"]    # PredRNN++ dropped from retraining (≈3× the cost of the others)
    BASELINE_LRS = [DEFAULT_LR]           # identical optimizer settings for every model (harmonized protocol)
    AUX_BASELINES = ["tau"]               # TAU is also offered NEX-ViP's auxiliary loss (chosen on validation)
    KTH_BASELINES, KTH_NEX_SEEDS = ["tau"], BASELINE_SEEDS
    MM_MODEL_LIST = ["nex_full", "tau"]
    EXTRA_SPLITS = [20260818]             # one more independent 9,000/1,000 split of the same 10,000 videos
    EXTRA_SPLIT_BASELINES = ["tau"]
    RUN_BASELINE_CHECKS = RUN_LOSS_ABLATIONS = False
elif COMPUTE_TIER == "full":
    BASELINES = ["tau", "simvpv2_gsta", "phydnet"]
    BASELINE_LRS = [DEFAULT_LR, 1e-3]     # each baseline's lr chosen on validation
    AUX_BASELINES = list(BASELINES)
    KTH_BASELINES, KTH_NEX_SEEDS = list(BASELINES), NEX_SEEDS
    MM_MODEL_LIST = ["nex_full", "tau", "simvpv2_gsta"]
    EXTRA_SPLITS = [20260818, 20260819]
    EXTRA_SPLIT_BASELINES = list(BASELINES)
    RUN_BASELINE_CHECKS = RUN_LOSS_ABLATIONS = True
else:
    raise ValueError('COMPUTE_TIER must be "critical" or "full"')
SPEED_FILE = ROOT / "analysis" / ("speed_" + re.sub(r"[^A-Za-z0-9]+", "_", GPU_NAME).strip("_") + f"_{PRECISION_ALL}.json")
if globals().get("MM_MODELS"):            # explicit choice in STEP 3C wins
    MM_MODEL_LIST = list(MM_MODELS)
PRINCIPAL = ["nex_full", "nex_identity"] + BASELINES
MOTION = "MOTION_SELECTED"                # placeholder: NEX-ViP loss chosen by gate 1 (plan A or plan B)
BEST = "BEST_BASELINE"                    # placeholder: strongest CLEVRER baseline on validation
LRSEL = "LR_SELECTED"                     # placeholder: baseline's learning rate chosen on validation
BLOSS = "BASELINE_LOSS_SELECTED"          # placeholder: baseline's loss (plain or NEX-ViP's auxiliary) chosen on validation
PLANB = "PLANB@"                          # placeholder prefix: plan-B sweep job, runs only if plan A fails


def J(phase, name, seed, loss="l1_ssim", dataset="clevrer", split_seed=20260817, windows=3, lr=DEFAULT_LR):
    return dict(phase=phase, dataset=dataset, split_seed=split_seed, name=name, seed=seed, precision=PRECISION_ALL,
                loss_kind=loss, windows=windows, lr=lr)


P1, P1B = "1 motion-loss weight sweep", "1b plan-B temporal-difference sweep"
P2, P3, P3B = "2 CLEVRER baselines (lr chosen on validation)", "3 NEX-ViP 5 seeds", "3b NEX-ViP component ablations"
P4, P5, P6, P7 = "4 Moving MNIST (standard benchmark)", "5 KTH", "6 strongest-baseline checks", "7 loss ablations"
P8 = "8 extra CLEVRER split (split sensitivity)"
jobs = [J(P1, "nex_full", SELECTION_SEED)]                                   # plain-loss reference for gate 1
jobs += [J(P1, "nex_full", SELECTION_SEED, f"l1_ssim_motion@{w:g}") for w in MOTION_WEIGHTS]
jobs += [J(P1B, "nex_full", SELECTION_SEED, f"{PLANB}{w:g}") for w in TDIFF_WEIGHTS]
jobs += [J(P2, b, SELECTION_SEED, lr=lr) for lr in BASELINE_LRS for b in BASELINES]            # lr choice
jobs += [J(P2, b, SELECTION_SEED, MOTION, lr=LRSEL) for b in AUX_BASELINES]                  # same auxiliary loss
jobs += [J(P2, b, s, BLOSS, lr=LRSEL) for s in BASELINE_SEEDS[1:] for b in BASELINES]         # chosen config
jobs += [J(P3, "nex_full", s, MOTION) for s in REPORT_SEEDS]
jobs += [J(P3, "nex_identity", s, MOTION) for s in NEX_SEEDS]
jobs += [J(P3, "nex_full", s) for s in REPORT_SEEDS]                              # plain loss, same 5 seeds
jobs += [J(P3, "nex_identity", s) for s in NEX_SEEDS]
jobs += [J(P3B, n, s, MOTION) for n in CLAIMED_ABLATIONS for s in BASELINE_SEEDS]
jobs += [J(P4, n, s, MOTION if n.startswith("nex_") else BLOSS, "mmnist", lr=DEFAULT_LR if n.startswith("nex_") else LRSEL)
         for n in MM_MODEL_LIST for s in globals().get("MM_SEEDS", BASELINE_SEEDS)]
jobs += [J(P5, "nex_full", s, MOTION, "kth", windows=KTH_WINDOWS) for s in KTH_NEX_SEEDS]
jobs += [J(P5, b, s, BLOSS, "kth", windows=KTH_WINDOWS, lr=LRSEL) for s in BASELINE_SEEDS for b in KTH_BASELINES]
if COMPUTE_TIER == "full":
    jobs += [J(P5, "nex_full", s, dataset="kth", windows=KTH_WINDOWS) for s in BASELINE_SEEDS]
    jobs += [J(P5, "nex_identity", s, MOTION, "kth", windows=KTH_WINDOWS) for s in BASELINE_SEEDS]
for sp in EXTRA_SPLITS:
    jobs += [J(P8, n, s, MOTION, split_seed=sp) for n in ("nex_full", "nex_identity") for s in BASELINE_SEEDS]
    jobs += [J(P8, b, s, BLOSS, split_seed=sp, lr=LRSEL) for b in EXTRA_SPLIT_BASELINES for s in BASELINE_SEEDS]
if RUN_BASELINE_CHECKS:
    jobs += [J(P6, BEST, s, "mse", lr=LRSEL) for s in BASELINE_SEEDS]                      # native MSE check
    jobs += [J(P6, b, SELECTION_SEED, "mse", "mmnist", lr=LRSEL) for b in MM_MODEL_LIST if not b.startswith("nex_")]
if RUN_LOSS_ABLATIONS:
    jobs += [J(P7, "nex_full", s, l) for l in ("l1", "ssim") for s in BASELINE_SEEDS]
atomic_json(ROOT / f"experiment_queue_v7_{COMPUTE_TIER}.json", jobs)

# ------------------------------------------------------------------ run lookup (precise status key)
CACHES = {CACHE["id"]: CACHE}
if globals().get("KTH_CACHE"):
    CACHES[KTH_CACHE["id"]] = KTH_CACHE
DATASET_CACHE = {"clevrer": CACHE, "kth": globals().get("KTH_CACHE"), "mmnist": globals().get("MM_DATA")}
SCIENTIFIC = ("name", "seed", "split", "loss", "precision", "epochs", "windows", "lr", "horizon", "initial_only", "cache")
EPOCHS = 20


def split_from_pool(split_seed):
    """Another independent 9,000/1,000 split of the SAME 10,000 cached CLEVRER videos (scheme and fractions as
    data.make_manifest's independent split; validation carved from the training part only). Saved and frozen."""
    saved = load_saved_manifest("clevrer", split_seed)
    if saved is not None:
        return saved
    paths = sorted(set(MANIFEST["training_pool"]) | set(MANIFEST["eval"]))
    rng = np.random.default_rng(split_seed)
    order = rng.permutation(len(paths))
    n = round(len(paths) * 0.1)
    test, train = [paths[i] for i in order[:n]], [paths[i] for i in order[n:]]
    order = rng.permutation(len(train))
    nv = max(1, round(0.1 * len(train)))
    m = {"dataset": "clevrer", "split_seed": split_seed, "scheme": "independent_video_split",
         "train": [train[i] for i in order[nv:]], "validation": [train[i] for i in order[:nv]], "eval": test,
         "training_pool": train}
    assert not set(m["train"]) & set(m["eval"]) and not set(m["validation"]) & set(m["eval"])
    m["id"] = digest(m)[:16]
    atomic_json(ROOT / "splits" / (m["id"] + ".json"), m)
    return m


def manifest_for_job(job):
    if job["dataset"] == "kth":
        return globals().get("KTH_MANIFEST")
    if job["split_seed"] != 20260817:
        return split_from_pool(job["split_seed"])
    return manifest_for(job["split_seed"])


def _scan_runs():
    table = {}
    for p in (ROOT / "runs").glob("*/config.json"):
        try:
            c = json.loads(p.read_text())
        except ValueError:
            continue
        key = tuple(c.get(k, DEFAULT_LR if k == "lr" else None) for k in SCIENTIFIC)
        table.setdefault(key, []).append(p.parent)
    return table


def _state(folder):
    return ("failed" if (folder / "FAILED.json").exists() else
            "evaluated" if (folder / "EVALUATED.json").exists() else "trained" if (folder / "DONE.json").exists()
            else "in progress" if (folder / "last.pt").exists() or (folder / "last.pt.previous").exists()
            else "started")


def find_run(job, table=None):
    """Exact match on every scientific setting (fixes the old name/seed/split/loss-only key)."""
    if job["dataset"] == "mmnist":
        return mm_find_run(job) if "mm_find_run" in globals() else (None, "waiting: run STEP 3C (Moving MNIST)")
    cache = DATASET_CACHE.get(job["dataset"])
    if cache is None:
        return None, "waiting: run STEP 3B (KTH)"
    man = globals().get("KTH_MANIFEST") if job["dataset"] == "kth" else load_saved_manifest("clevrer", job["split_seed"])
    if man is None:
        return None, "not started"
    key = (job["name"], job["seed"], man["id"], job["loss_kind"], job["precision"], EPOCHS, job["windows"],
           float(job["lr"]), 10, False, cache["id"])
    hits = (table if table is not None else _scan_runs()).get(key, [])
    if not hits:
        return None, "not started"
    rank = {"evaluated": 3, "trained": 2, "failed": 1.5, "in progress": 1, "started": 0}
    best = max(hits, key=lambda f: rank[_state(f)])
    return best, _state(best)


# ------------------------------------------------------------------ diagnostics for any finished run
def run_diagnostics(folder):
    """Validation skill (t+1, t+10) and change ratio of the selected checkpoint. Uses the v6 log when
    present, otherwise measures it once on the validation videos and caches it in the run folder."""
    folder = Path(folder)
    done = json.loads((folder / "DONE.json").read_text()) if (folder / "DONE.json").exists() else {}
    if "best_epoch_diagnostics" in done:
        return done["best_epoch_diagnostics"] | {k: done[k] for k in ("collapsed", "sanity_gate_pass")}
    cached = folder / "diagnostics_v6.json"
    if cached.exists():
        return json.loads(cached.read_text())
    if not (folder / "best.pt").exists():
        return None
    cfg = json.loads((folder / "config.json").read_text())
    cache = CACHES.get(cfg["cache"])
    man_path = ROOT / "splits" / (cfg["split"] + ".json")
    if cache is None or not man_path.exists():
        return None
    model, _ = _engine.load_run(folder, DEVICE)
    d = _engine.validation_diagnostics(model, cache, json.loads(man_path.read_text()), cfg["seed"], cfg["horizon"])
    del model
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    d = {k: (v if not isinstance(v, float) or math.isfinite(v) else None) for k, v in d.items()}
    atomic_json(cached, d | {"measured_by": PATCH_ID, "note": "measured after training on validation videos"})
    return d


def _plain_reference(name="nex_full", seed=None):
    f, st = find_run(J("ref", name, SELECTION_SEED if seed is None else seed))
    return run_diagnostics(f) if f is not None and st in ("trained", "evaluated") else None


SELECTION_FILE = ROOT / "analysis" / "nex_loss_selection.json"
_LOGGED_CHANGES = set()


def _gate(row, plain):
    """Gate 1 for one candidate loss (validation only): not collapsed, better than the plain loss at t+10,
    and (REQUIRE_BEAT_COPY) better than copying the last frame at t+10."""
    s = row.get("val_skill_th")
    if s is None or not math.isfinite(s) or row.get("collapsed") or plain is None or plain.get("val_skill_th") is None:
        return False
    if not s > plain["val_skill_th"] + GATE_MARGIN:
        return False
    return (s > GATE_MARGIN) if REQUIRE_BEAT_COPY else True


def log_selection(kind, record):
    """Append-only audit trail of every validation-based selection (with time and candidate run ids)."""
    with open(ROOT / "analysis" / "selection_log.jsonl", "a") as fh:
        fh.write(json.dumps({"time": time.strftime("%Y-%m-%d %H:%M:%S"), "kind": kind, "patch_id": PATCH_ID,
                             "record": record}, default=str) + "\n")


def _sweep(kind, weights):
    """Diagnostics of a seed-2024 sweep; None while any run is unfinished."""
    rows = []
    for w in weights:
        loss = f"l1_ssim_{kind}@{w:g}"
        f, st = find_run(J("sweep", "nex_full", SELECTION_SEED, loss))
        if st == "failed":                  # diverged candidate: recorded, cannot pass gate 1 (never retried)
            rows.append({"plan": "A" if kind == "motion" else "B", "weight": w, "loss": loss, "run": f.name,
                         "val_skill_th": None, "collapsed": None, "failed": True})
            continue
        if f is None or st not in ("trained", "evaluated"):
            return None
        d = run_diagnostics(f)
        if not d or d.get("val_skill_th") is None:
            return None                     # diagnostics missing: wait rather than decide on partial information
        rows.append({"plan": "A" if kind == "motion" else "B", "weight": w, "loss": loss, "run": f.name, **d})
    return rows


def plan_a_status():
    """'waiting', 'passed' or 'failed' (plan A = temporal-change loss sweep)."""
    if SELECTION_FILE.exists():
        rec = json.loads(SELECTION_FILE.read_text())
        if rec.get("settings") == _gate_settings():
            return "passed" if any(_gate(r, rec["plain_reference"]) for r in rec["plan_a"]) else "failed"
    rows, plain = _sweep("motion", MOTION_WEIGHTS), _plain_reference()
    if rows is None or plain is None:
        return "waiting"
    return "passed" if any(_gate(r, plain) for r in rows) else "failed"


def _gate_settings():
    return {"motion_weights": MOTION_WEIGHTS, "tdiff_weights": TDIFF_WEIGHTS, "require_beat_copy": REQUIRE_BEAT_COPY,
            "margin": GATE_MARGIN, "selection_seed": SELECTION_SEED, "precision": PRECISION_ALL}


def resolve_motion():
    """Gate 1: choose NEX-ViP's loss on VALIDATION (seed 2024). Plan A (temporal-change loss) first; plan B
    (temporal-difference loss) only if no plan-A weight passes. Returns (loss_kind, reason)."""
    settings = _gate_settings()
    if SELECTION_FILE.exists():
        rec = json.loads(SELECTION_FILE.read_text())
        if rec.get("settings") == settings:
            if rec["selected_loss"] is None and not (ALLOW_MOTION_IF_NO_GAIN and rec.get("fallback_loss")):
                if IF_GATE1_FAILS == "paper_loss" and not rec.get("all_diverged"):
                    return PAPER_LOSS, "selected (gate 1 not passed → published L1+SSIM loss)"
                return None, "blocked: " + rec["verdict"]
            return rec["selected_loss"] or rec.get("fallback_loss"), "selected"
        if json.dumps(settings, sort_keys=True) not in _LOGGED_CHANGES:
            _LOGGED_CHANGES.add(json.dumps(settings, sort_keys=True))
            log_selection("gate1_settings_changed", {"old": rec.get("settings"), "new": settings})
    plain = _plain_reference()
    if plain is None and find_run(J("ref", "nex_full", SELECTION_SEED))[1] == "failed":
        return None, ("blocked (diverged): the plain NEX-ViP reference (L1+SSIM, seed 2024) diverged (runs/*/FAILED.json). Gate 1 "
                      "cannot be decided; inspect the failure (e.g. set PRECISION_ALL = \"fp32\") before continuing")
    if plain is None or plain.get("val_skill_th") is None:
        return None, "waiting: plain NEX-ViP (L1+SSIM, seed 2024) needs training/diagnostics first (phase 3)"
    rows_a = _sweep("motion", MOTION_WEIGHTS)
    if rows_a is None:
        return None, "waiting: motion-loss weight sweep (phase 1) not finished"
    passing, rows_b = [r for r in rows_a if _gate(r, plain)], None
    if not passing:
        rows_b = _sweep("tdiff", TDIFF_WEIGHTS)
        if rows_b is None:
            return None, "waiting: plan A failed gate 1 → plan-B sweep (phase 1b) not finished"
        passing = [r for r in rows_b if _gate(r, plain)]
    choice = max(passing, key=lambda r: (r["val_skill_th"], -r["weight"])) if passing else None
    _all = rows_a + (rows_b or [])
    if choice is None and _all and all(r.get("failed") for r in _all):
        return None, ("blocked (diverged): every gate-1 candidate diverged (runs/*/FAILED.json) - a training failure, "
                      "not a result. Inspect the failures (e.g. PRECISION_ALL = \"fp32\") before deciding anything")
    usable = [r for r in (rows_a + (rows_b or [])) if r.get("val_skill_th") is not None and not r.get("collapsed")]
    fallback = max(usable, key=lambda r: r["val_skill_th"])["loss"] if usable else None
    _paper = choice is None and IF_GATE1_FAILS == "paper_loss" and not ALLOW_MOTION_IF_NO_GAIN
    verdict = (f"plan {choice['plan']} passed gate 1 with {choice['loss']}" if choice else
               "neither the temporal-change loss (plan A) nor the temporal-difference loss (plan B) beat both the "
               "plain loss and copy-last-frame on validation. "
               + ("NEX-ViP continues with its published L1+SSIM loss (IF_GATE1_FAILS = \"paper_loss\"); report the "
                  "auxiliary-loss sweep as a negative result." if _paper else
                  "Stop NEX-ViP training and reframe the paper (see STEP 5 notes).")
               + (f" NOTE: {sum(bool(r.get('failed')) for r in _all)} candidate(s) DIVERGED "
                                        "(runs/*/FAILED.json) — check them before concluding." if any(r.get("failed")
                                        for r in _all) else ""))
    rec = {"settings": settings, "criterion": f"gate 1 on validation, seed {SELECTION_SEED}: not collapsed, skill t+10 > plain loss + {GATE_MARGIN}"
           + (f" and > {GATE_MARGIN} (beats copy-last-frame)" if REQUIRE_BEAT_COPY else "") + "; among passing: max skill, tie → smaller weight",
           "plain_reference": plain, "plan_a": rows_a, "plan_b": rows_b,
           "selected_loss": choice["loss"] if choice else None, "fallback_loss": fallback, "verdict": verdict,
           "improves_over_plain": bool(choice), "if_gate1_fails": IF_GATE1_FAILS,
           "applied_loss": choice["loss"] if choice else (PAPER_LOSS if _paper else None)}
    atomic_json(SELECTION_FILE, rec)
    log_selection("gate1", rec)
    fmt = lambda v: "n/a" if v is None else f"{v:+.4f}"
    print("Gate 1 — NEX-ViP loss selection (validation only, seed 2024):",
          *(f"\n   plan {r['plan']} {r['loss']}: skill t+10 {fmt(r.get('val_skill_th'))} · change ratio "
            f"{fmt(r.get('val_change_ratio'))}{' · COLLAPSED' if r.get('collapsed') else ''}{' · FAILED (diverged)' if r.get('failed') else ''}"
            f"{' · PASS' if _gate(r, plain) else ''}" for r in rows_a + (rows_b or [])),
          f"\n   plain L1+SSIM: skill t+10 {fmt(None if plain is None else plain.get('val_skill_th'))}",
          f"\n   → {verdict}")
    if choice is None and not (ALLOW_MOTION_IF_NO_GAIN and fallback):
        if _paper:
            return PAPER_LOSS, "selected (gate 1 not passed → published L1+SSIM loss)"
        return None, "blocked: " + verdict
    return (choice or {"loss": fallback})["loss"], "selected"


def _js(v):
    """JSON-safe score: a diverged (FAILED) candidate is recorded as 'failed'."""
    return v if v is None or math.isfinite(v) else "failed"


def _val_skill(job):
    """Validation skill at t+10 of a trained run, None if not ready."""
    f, st = find_run(job)
    if st == "failed":
        return float("-inf")               # diverged candidate: loses the selection (recorded in FAILED.json)
    if f is None or st not in ("trained", "evaluated"):
        return None
    d = run_diagnostics(f) or {}
    v = d.get("val_skill_th")
    return v if v is not None and math.isfinite(v) else None


def resolve_baseline_lr(name):
    """Each baseline's learning rate = higher VALIDATION skill at t+10 (selection seed, CLEVRER, plain loss)."""
    sel = ROOT / "analysis" / "baseline_lr_selection.json"
    rec = json.loads(sel.read_text()) if sel.exists() else {}
    if name in rec and rec[name]["candidates"] == BASELINE_LRS and rec[name].get("precision") == PRECISION_ALL:
        return rec[name]["lr"], "selected"
    scores = {lr: _val_skill(J("lr", name, SELECTION_SEED, lr=lr)) for lr in BASELINE_LRS}
    if any(v is None for v in scores.values()):
        return None, f"waiting: {name} learning-rate runs (phase 2, seed {SELECTION_SEED}) not finished"
    lr = max(scores, key=lambda k: (scores[k], k == DEFAULT_LR))
    rec[name] = {"candidates": BASELINE_LRS, "val_skill_t10": {str(k): _js(v) for k, v in scores.items()}, "lr": lr,
                 "precision": PRECISION_ALL,
                 "criterion": f"max validation skill at t+10, seed {SELECTION_SEED}, CLEVRER, plain loss; tie → default lr"}
    atomic_json(sel, rec)
    log_selection("baseline_lr", {name: rec[name]})
    print(f"Learning rate for {name} (validation only): {lr:g}  {rec[name]['val_skill_t10']}")
    return lr, "selected"


def resolve_baseline_loss(name):
    """Each baseline gets the same loss options as NEX-ViP: plain L1+SSIM or NEX-ViP's gate-1 auxiliary loss,
    chosen on VALIDATION skill at t+10 (selection seed, CLEVRER, at its chosen lr). Tie → plain."""
    sel = ROOT / "analysis" / "baseline_loss_selection.json"
    rec = json.loads(sel.read_text()) if sel.exists() else {}
    if name not in AUX_BASELINES:          # this compute tier offers no auxiliary candidate to this baseline
        r0 = rec.get(name, {})
        if r0.get("aux_candidate", "x") is not None or r0.get("loss") != "l1_ssim" or r0.get("precision") != PRECISION_ALL:
            rec[name] = {"aux_candidate": None, "loss": "l1_ssim", "precision": PRECISION_ALL,
                         "note": f"plain loss only ({COMPUTE_TIER} tier: no auxiliary-loss candidate for this baseline)"}
            atomic_json(sel, rec)
            log_selection("baseline_loss", {name: rec[name]})
        return "l1_ssim", "selected"
    aux, why = resolve_motion()
    if aux is None and (not why.startswith("blocked") or why.startswith("blocked (diverged)")):
        return None, why
    if aux == PAPER_LOSS:                  # gate 1 not passed: there is no auxiliary loss to offer the baseline
        aux = None
    if name in rec and rec[name].get("aux_candidate") == aux and rec[name].get("precision") == PRECISION_ALL:
        return rec[name]["loss"], "selected"
    lr, why = resolve_baseline_lr(name)
    if lr is None:
        return None, why
    scores = {"l1_ssim": _val_skill(J("l", name, SELECTION_SEED, lr=lr))}
    if aux is not None:
        scores[aux] = _val_skill(J("l", name, SELECTION_SEED, aux, lr=lr))
    if any(v is None for v in scores.values()):
        return None, f"waiting: {name} loss runs (phase 2, seed {SELECTION_SEED}) not finished"
    loss = max(scores, key=lambda k: (scores[k], k == "l1_ssim"))
    rec[name] = {"aux_candidate": aux, "val_skill_t10": {k: _js(v) for k, v in scores.items()}, "loss": loss, "lr": lr,
                 "precision": PRECISION_ALL,
                 "criterion": f"max validation skill at t+10, seed {SELECTION_SEED}, CLEVRER, chosen lr; tie → plain"}
    atomic_json(sel, rec)
    log_selection("baseline_loss", {name: rec[name]})
    print(f"Loss for {name} (validation only): {loss}  {scores}")
    return loss, "selected"


def resolve_best_baseline():
    """Strongest baseline = highest mean VALIDATION skill at t+10 over seeds, each at its chosen lr and loss."""
    sel = ROOT / "analysis" / "best_baseline.json"
    def _snapshot():
        out = {}
        for f_ in ("baseline_lr_selection.json", "baseline_loss_selection.json"):
            p_ = ROOT / "analysis" / f_
            out[f_] = {k: [v.get("lr"), v.get("loss"), v.get("precision")]
                       for k, v in json.loads(p_.read_text()).items()} if p_.exists() else {}
        return json.loads(json.dumps(out))      # JSON round trip so the comparison with the saved snapshot is exact
    if sel.exists():
        rec = json.loads(sel.read_text())
        if rec.get("config_selected") and rec.get("snapshot") == _snapshot():
            return rec["best"], "selected"
    scores = {}
    for b in BASELINES:
        lr, why = resolve_baseline_lr(b)
        loss, why2 = resolve_baseline_loss(b) if lr is not None else (None, why)
        if lr is None or loss is None:
            return None, why if lr is None else why2
        vals = [_val_skill(J("b", b, s, loss, lr=lr)) for s in BASELINE_SEEDS]
        if None in vals:
            return None, "waiting: CLEVRER baselines (phase 2) not finished"
        scores[b] = float(np.mean(vals))
    best = max(scores, key=scores.get)
    rec = {"criterion": "mean validation skill at t+10 over seeds " + str(BASELINE_SEEDS) + ", chosen lr and loss",
           "scores": {k: _js(v) for k, v in scores.items()}, "best": best, "config_selected": True, "snapshot": _snapshot()}
    atomic_json(sel, rec)
    log_selection("best_baseline", rec)
    print("Strongest baseline on validation:", best, scores)
    return best, "selected"


def selection_pending(job):
    """True while a run is a candidate (or the plain reference) of a validation selection that is not decided
    under the CURRENT settings: its TEST evaluation waits, so no test number can precede a selection."""
    if job["dataset"] != "clevrer" or job["seed"] != SELECTION_SEED:
        return False
    if job["name"] == "nex_full":
        if not SELECTION_FILE.exists():
            return True
        rec = json.loads(SELECTION_FILE.read_text())
        if rec.get("settings") != _gate_settings():
            return True
        if job["loss_kind"] == "l1_ssim":
            return False
        cands = {r["loss"] for r in (rec.get("plan_a") or []) + (rec.get("plan_b") or [])}
        return bool(aux_loss_type(job["loss_kind"])) and job["loss_kind"] not in cands
    if job["name"] in BASELINES:
        sl, sb = ROOT / "analysis" / "baseline_lr_selection.json", ROOT / "analysis" / "baseline_loss_selection.json"
        lr_rec = json.loads(sl.read_text()).get(job["name"]) if sl.exists() else None
        if not lr_rec or lr_rec.get("candidates") != BASELINE_LRS or lr_rec.get("precision") != PRECISION_ALL:
            return True
        if job["name"] not in AUX_BASELINES:
            return False                    # loss is fixed (plain) for this baseline in this tier
        if not SELECTION_FILE.exists() or json.loads(SELECTION_FILE.read_text()).get("settings") != _gate_settings():
            return True                     # the auxiliary candidate is not known yet
        g1 = json.loads(SELECTION_FILE.read_text())
        aux = g1.get("selected_loss") or (g1.get("fallback_loss") if ALLOW_MOTION_IF_NO_GAIN else None)
        aux = None if aux == PAPER_LOSS else aux
        loss_rec = json.loads(sb.read_text()).get(job["name"]) if sb.exists() else None
        return not (loss_rec and loss_rec.get("aux_candidate") == aux and loss_rec.get("precision") == PRECISION_ALL)
    return False


def resolve(job):
    """Fill placeholders; returns (job or None, reason). Reasons: 'ok', 'waiting: …', 'blocked: …', 'skipped: …'."""
    job = dict(job)
    if job["loss_kind"].startswith(PLANB):
        st = plan_a_status()
        if st == "waiting":
            return None, "waiting: plan-B sweep runs only if plan A fails gate 1"
        if st == "passed":
            return None, "skipped: plan A passed gate 1 (plan B not needed)"
        job["loss_kind"] = "l1_ssim_tdiff@" + job["loss_kind"][len(PLANB):]
    if job["loss_kind"] == MOTION:
        loss, why = resolve_motion()
        if loss is None:
            return None, why
        job["loss_kind"] = loss
    if job["name"] == BEST:
        name, why = resolve_best_baseline()
        if name is None:
            return None, why
        job["name"] = name
    if job["lr"] == LRSEL:
        lr, why = resolve_baseline_lr(job["name"])
        if lr is None:
            return None, why
        job["lr"] = lr
    if job["loss_kind"] == BLOSS:
        loss, why = resolve_baseline_loss(job["name"])
        if loss is None:
            return None, why
        job["loss_kind"] = loss
    return job, "ok"


# ------------------------------------------------------------------ free-tier planning (estimates only)
# Priority groups (STEP 5 runs the groups in RUN_GROUPS, in this order):
#   1 = essential: gate 1 (plan A / plan B), CLEVRER baselines, NEX-ViP 5 seeds, residual-design ablations;
#   2 = Moving MNIST (standard benchmark); 3 = KTH (real-world video); 4 = extra CLEVRER split (split sensitivity);
#   5 = baseline checks / loss ablations (full tier only).
GROUP_OF_PHASE = {"1": 1, "1b": 1, "2": 1, "3": 1, "3b": 1, "4": 2, "5": 3, "8": 4, "6": 5, "7": 5}
GROUP_NAME = {1: "essential (gate 1, CLEVRER baselines, NEX-ViP seeds, ablations)", 2: "Moving MNIST (standard benchmark)",
              3: "KTH (real-world video)", 4: "extra CLEVRER split", 5: "baseline checks / loss ablations"}
EVAL_WINDOWS_PER_VIDEO = 3
SPEEDCHECK_EVAL_FACTOR = 1.5   # STEP 4B times forecasts only; metrics add overhead (replaced by real timings)


def job_group(job):
    return GROUP_OF_PHASE.get(job["phase"].split()[0], 5)


def _arch_options(job):
    if job["name"] == BEST:
        r = resolve_best_baseline()[0] if (ROOT / "analysis" / "best_baseline.json").exists() else None
        return [r] if r else list(BASELINES)
    return [job["name"]]


def _done_updates(folder, per_epoch):
    try:
        p = json.loads((folder / "progress.json").read_text())
        return int(p["updates"])
    except (OSError, ValueError, KeyError):
        pass
    try:
        return len(pd.read_csv(folder / "history.csv")) * per_epoch
    except (OSError, ValueError):
        return 0


def _persistence_reusable(dataset):
    man = DATASET_CACHE.get(dataset) and manifest_for_job({"dataset": dataset, "split_seed": 20260817})
    if not man:
        return False
    for spec_path in (ROOT / "evaluation").glob("*/spec.json"):
        try:
            sp = json.loads(spec_path.read_text())
        except ValueError:
            continue
        if sp.get("model") == "persistence" and sp.get("split") == man["id"] and (spec_path.parent / "DONE.json").exists():
            return True
    return False


def estimate_job(job, table=None, runs=None):
    """Estimated seconds still needed: {'train', 'eval', 'validation'} or None if this GPU has no timings yet.
    Placeholder jobs (motion weight / strongest baseline not chosen yet) use the slowest candidate."""
    if DATASET_CACHE.get(job["dataset"]) is None:
        return None
    table = table or load_speed()
    rj, why = resolve(job)
    if rj is None and why.startswith(("skipped", "blocked")):
        return {"train": 0.0, "eval": 0.0, "validation": 0.0}
    if job["dataset"] == "mmnist":
        return mm_estimate(rj, table) if rj is not None and "mm_estimate" in globals() else None
    man = manifest_for_job(job)
    per_epoch = math.ceil(len(man["train"]) * job["windows"] / 32)
    n_val, n_eval = len(man["validation"]), len(man["eval"]) * EVAL_WINDOWS_PER_VIDEO
    folder, st = find_run(rj, runs) if rj else (None, "not started")
    if st in ("evaluated", "failed"):
        return {"train": 0.0, "eval": 0.0, "validation": 0.0}
    best = None
    for arch in _arch_options(job):
        sp = speed_lookup(job["dataset"], arch, table)
        if not sp or "s_per_update" not in sp or "eval_s_per_window" not in sp:
            return None
        ev = sp["eval_s_per_window"] * (SPEEDCHECK_EVAL_FACTOR if sp.get("eval_s_per_window_source") == "speedcheck" else 1)
        val = sp.get("validation_seconds") or n_val * ev / 3          # horizon 10 instead of 30
        done = _done_updates(folder, per_epoch) if folder is not None and st != "trained" else 0
        left_updates = 0 if st == "trained" else max(0, EPOCHS * per_epoch - done)
        left_epochs = 0 if st == "trained" else EPOCHS - done // per_epoch
        e = {"train": left_updates * sp["s_per_update"] + left_epochs * val,
             "eval": n_eval * ev * (1.0 if _persistence_reusable(job["dataset"]) else 1.5),
             "validation": val}
        if best is None or e["train"] + e["eval"] > best["train"] + best["eval"]:
            best = e
    return best


def print_estimates(job_list, usable_hours, groups=(1, 2, 3, 4)):
    """Remaining GPU hours and free-tier sessions per priority group (estimates, refined as runs progress)."""
    table, runs = load_speed(), _scan_runs()
    seen, tot, unknown = set(), {}, {}
    for j in job_list:
        g = job_group(j)
        if g not in groups:
            continue
        ident = json.dumps({k: v for k, v in j.items() if k != "phase"}, sort_keys=True)
        if ident in seen:
            continue
        seen.add(ident)
        e = estimate_job(j, table, runs)
        if e is None:
            unknown[g] = unknown.get(g, 0) + 1
            continue
        tot[g] = tot.get(g, 0.0) + e["train"] + e["eval"]
    print(f"Estimated GPU time still needed (this GPU: {GPU_NAME}; {usable_hours:.1f} usable h per session):")
    cumulative = 0.0
    for g in sorted(set(tot) | set(unknown)):
        h = tot.get(g, 0.0) / 3600
        cumulative += h
        extra = f" (+{unknown[g]} jobs without timings: run STEP 4B / load KTH)" if unknown.get(g) else ""
        print(f"   group {g} {GROUP_NAME[g]:58s} {h:6.1f} h ≈ {h/usable_hours:4.1f} sessions"
              f" | cumulative {cumulative:6.1f} h ≈ {cumulative/usable_hours:4.1f} sessions{extra}")
    print("   (estimates use measured speeds on this GPU; they are refined automatically after every session)")


