"""## STEP 5 — Train + evaluate within the session budget (Run all / rerun to continue)"""

# ═════════ STEP 5 — Train and evaluate the v6 queue within this session's time budget (rerun / Run all to continue) ═════════
# Critical path first: group 1 (gate 1: motion-loss sweep, plan B only if needed → CLEVRER baselines → NEX-ViP seeds
# → identity transition → claimed ablations) → group 2 (Moving MNIST) → group 3 (KTH) → group 4 (extra CLEVRER split)
# → group 5 (strongest-baseline checks / loss ablations; queued only in the "full" compute tier).
# Time budget: the session clock from STEP 1 (FREE_TIER_HOURS − SAFETY_MINUTES). Work stops cleanly before it:
#   • a job is started only if it can finish here, or can train for at least MIN_TRAIN_MINUTES;
#   • training saves and pauses at the deadline, also before an end-of-epoch validation that would not fit;
#   • evaluation saves finished windows and pauses at the deadline; next session continues from there.
# Every epoch prints validation skill vs copy-last-frame and a COLLAPSED / sanity warning when relevant.
RUN_GROUPS = [1, 2, 3, 4, 5]   # 1 essential CLEVRER · 2 Moving MNIST · 3 KTH · 4 extra CLEVRER split · 5 checks + loss ablations (only queued in the "full" tier)
ONLY_PHASES = None       # e.g. ["1 motion-loss weight sweep"] to restrict this session; None = all in RUN_GROUPS
MIN_TRAIN_MINUTES = 20   # don't start a job that cannot finish unless it can train at least this long
SAVE_RESERVE_MINUTES = 5 # kept free for the final checkpoint save + Drive upload
STOP_BELOW_MINUTES = 3   # with less session time than this, nothing new is started (not even an evaluation)
STOP_IF_GATE1_FAILS = True   # stop the queue when gate 1 is BLOCKED: always if training diverged; if no loss passes
                             # only when IF_GATE1_FAILS = "stop" (STEP 4). v7.1 default "paper_loss" keeps going with
                             # NEX-ViP's published L1+SSIM loss so every reviewer experiment still runs
AUTO_CLEAN_FINISHED = True   # after a run is trained AND evaluated, delete its resume-only files (last.pt,
                             # last.pt.previous, best.pt.previous) to fit the 15 GB free Drive. best.pt is kept.
                             # Deleted files go to Drive Trash: empty it at drive.google.com to free the space.

