try:
    _drive_free = shutil.disk_usage(ROOT).free / 1e9
    if _drive_free < MIN_DRIVE_FREE_GB:
        _pf.append(f"Google Drive almost full ({_drive_free:.1f} GB free): run STEP 6 and empty Drive Trash")
except OSError as _e:
    _pf.append(f"Drive folder not reachable ({_e}): rerun STEP 1")
if shutil.disk_usage("/content" if os.path.isdir("/content") else "/").free / 1e9 < MIN_LOCAL_FREE_GB:
    _pf.append("local disk almost full: Runtime → Disconnect and delete runtime, then Run all")
if _pf:
    QUEUE_COMPLETE = False
    raise SystemExit("STEP 5 not started (nothing was changed):\n  • " + "\n  • ".join(_pf))
# One session per folder: a heartbeat lock (refreshed every 5 min) blocks a second, simultaneous session.
import threading, uuid
FORCE_UNLOCK = False      # True only if you are SURE no other session is running (e.g. it crashed < 20 min ago)
_LOCK = ROOT / "SESSION_LOCK.json"
_SID = Path("/content/.nexvip_session_id") if os.path.isdir("/content") else LOCAL / ".nexvip_session_id"
SESSION_ID = globals().get("SESSION_ID") or (_SID.read_text().strip() if _SID.exists() else uuid.uuid4().hex[:12])
try:
    _SID.write_text(SESSION_ID)
except OSError:
    pass
try:
    _held = json.loads(_LOCK.read_text()) if _LOCK.exists() else {}
except ValueError:
    _held = {}
if _held and _held.get("session") != SESSION_ID and time.time() - _held.get("heartbeat", 0) < 20 * 60 and not FORCE_UNLOCK:
    QUEUE_COMPLETE = False
    raise SystemExit(f"STEP 5 not started: another session is using this folder (last heartbeat "
                     f"{(time.time() - _held['heartbeat']) / 60:.0f} min ago). Never run two sessions at once. "
                     "If that session is dead, wait 20 min or set FORCE_UNLOCK = True.")
def _beat():
    atomic_json(_LOCK, {"session": SESSION_ID, "heartbeat": time.time(),
                        "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu"})
_beat()                    # take the lock NOW (synchronously), then keep it alive in the background
def _heartbeat():
    while True:
        time.sleep(300)
        try:
            _beat()
        except OSError:
            pass
if not globals().get("_HEARTBEAT_STARTED"):
    threading.Thread(target=_heartbeat, daemon=True).start()
    _HEARTBEAT_STARTED = True
print(f"Preflight OK | GPU {torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'cpu'} | "
      f"Drive free {_drive_free:.0f} GB | prefetch {PREFETCH_BATCHES} batches | "
      f"full batch on this GPU: {torch.cuda.is_available() and torch.cuda.get_device_properties(0).total_memory >= FULL_BATCH_GPU_GIB * 2**30}")
