def persistence_evaluation(cache, manifest, seed, archive, deadline):
    """Copy-last-frame forecasts do not depend on the training seed: reuse a complete persistence evaluation
    of the same split/cache/masks (rows copied with this seed) instead of recomputing identical numbers."""
    spec = eval_spec(cache, manifest, "persistence", seed, "no_weights", archive=archive)
    target = ROOT / "evaluation" / digest(spec)[:16]
    if (target / "DONE.json").exists():
        return target / "per_window.csv"
    same = ("split", "cache", "windows", "initial_only", "horizons", "pilot_limit", "mask_archive", "source")
    for sp in sorted((ROOT / "evaluation").glob("*/spec.json")):
        try:
            other = json.loads(sp.read_text())
        except ValueError:
            continue
        if other.get("model") == "persistence" and all(other.get(k) == spec[k] for k in same) \
                and (sp.parent / "DONE.json").exists() and (sp.parent / "per_window.csv").exists():
            rows = pd.read_csv(sp.parent / "per_window.csv")
            rows["seed"] = seed
            target.mkdir(parents=True, exist_ok=True)
            atomic_json(target / "spec.json", spec)
            atomic_csv(target / "per_window.csv", rows)
            atomic_json(target / "DONE.json", {"complete_windows": int(rows[["video", "start"]].drop_duplicates().shape[0]),
                                               "pilot": False, "copied_from": sp.parent.name,
                                               "note": "persistence forecasts are seed-independent; rows copied"})
            print(f"  persistence: reused evaluation {sp.parent.name} (seed-independent)", flush=True)
            return target / "per_window.csv"
    return _evaluation.evaluate(Predictor("persistence", DEVICE), cache, manifest, "persistence", seed,
                                "no_weights", archive=archive, deadline=deadline)


def evaluate_run(folder, deadline=None):
    """Evaluates a trained run on the held-out videos. Returns False if paused at the deadline."""
    cfg = json.loads((folder / "config.json").read_text())
    manifest = json.loads((ROOT / "splits" / (cfg["split"] + ".json")).read_text())
    cache = CACHES[cfg["cache"]]
    archive = PROPOSALS if manifest["dataset"] == "clevrer" else None
    model, _ = _engine.load_run(folder, DEVICE)
    result = _evaluation.evaluate(model, cache, manifest, _engine.run_label(cfg), cfg["seed"],
                                  sha(folder / "best.pt"), archive=archive, deadline=deadline)
    if result is not None and LAST_EVAL.get("windows", 0) >= 32:
        record_speed(manifest["dataset"], cfg["name"], "observed",
                     eval_s_per_window=LAST_EVAL["seconds"] / LAST_EVAL["windows"])
    if result is not None and cfg["seed"] == 2024 and (deadline is None or time.monotonic() < deadline):
        qualitative(model, cache, manifest, ROOT / "qualitative" / folder.name)
    del model
    gc.collect()
    torch.cuda.empty_cache()
    if result is None:
        return False
    persistent = persistence_evaluation(cache, manifest, cfg["seed"], archive, deadline)
    if persistent is None:
        return False
    atomic_json(folder / "EVALUATED.json", {"metrics": str(result), "persistence": str(persistent)})
    print(f"  ✓ evaluated {_engine.run_label(cfg)} seed {cfg['seed']} ({manifest['dataset']})", flush=True)
    return True


def diverged(err):
    """Training diverged (nonfinite loss / gradient): recorded as FAILED, never retried in a loop."""
    return isinstance(err, FloatingPointError) or "finite" in str(err).lower()


def mark_failed(folder, rjob, err):
    if folder is None:
        raise err
    atomic_json(folder / "FAILED.json", {"reason": f"{type(err).__name__}: {err}", "job": {k: str(v) for k, v in rjob.items()},
                                         "note": "diverged during training; kept as a failed run (reported, never retried)"})
    failed_now.append(rjob)
    print(f"  ⚠ run diverged and is recorded as FAILED (it loses any selection it was a candidate for): {err}", flush=True)


def clean_finished(folder):
    if not (AUTO_CLEAN_FINISHED and (folder / "DONE.json").exists() and (folder / "EVALUATED.json").exists()
            and (folder / "best.pt").exists()):
        return 0
    freed = 0
    for name in ("last.pt", "last.pt.previous", "best.pt.previous"):
        f = folder / name
        if f.exists():
            freed += f.stat().st_size
            f.unlink()
    return freed


def report_gate(folder):
    d = run_diagnostics(folder)
    if not d:
        return
    msg = (f"  validation: skill t+1 {d.get('val_skill_t1', float('nan')):+.3f} · skill t+10 "
           f"{d.get('val_skill_th', float('nan')):+.3f} · change ratio {d.get('val_change_ratio', float('nan')):.2f}")
    if d.get("collapsed"):
        msg += "\n  ⚠ COLLAPSED: forecasts barely move from the last input frame (copy-last-frame behaviour)."
    if not d.get("sanity_gate_pass"):
        msg += "\n  ⚠ SANITY GATE FAILED: worse than copying the last frame at t+1 → undertrained or misconfigured; it is marked ‡ and must not be presented as a tuned model."
    print(msg, flush=True)


