MAX_JOB_ERRORS = 3          # unattended: a job that crashes (not divergence) is skipped and logged; after this many
JOB_ERRORS = []             # errors in one session the queue stops cleanly (no compute units burned on a broken setup)


def job_error(rjob, err):
    """Logs a non-divergence crash of one job to analysis/job_errors.jsonl; True = stop the queue."""
    import traceback
    JOB_ERRORS.append(f"{rjob['name']} seed {rjob['seed']} ({rjob['dataset']}): {type(err).__name__}: {err}")
    try:
        with open(ROOT / "analysis" / "job_errors.jsonl", "a") as fh:
            fh.write(json.dumps({"time": time.strftime("%Y-%m-%d %H:%M:%S"), "job": {k: str(v) for k, v in rjob.items()},
                                 "error": f"{type(err).__name__}: {err}",
                                 "trace": traceback.format_exc()[-3000:]}) + "\n")
    except OSError:
        pass
    print(f"  ✗ job skipped after an error ({len(JOB_ERRORS)}/{MAX_JOB_ERRORS}): {type(err).__name__}: {err}", flush=True)
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    time.sleep(30)                                   # let a transient Drive/CUDA hiccup settle
    return len(JOB_ERRORS) >= MAX_JOB_ERRORS


def deadline_mono(extra_reserve=0.0):
    """time.monotonic() value at which work must stop (session deadline minus reserves)."""
    return time.monotonic() + session_left_s() - extra_reserve


