    KTH_TRAIN_WINDOWS = globals().get("KTH_WINDOWS", 15)   # KTH protocol reported in the main tables
    OUT = ROOT / "final_report"
    FIG = OUT / "figures"
    TAB = OUT / "tables"
    for d in (OUT, FIG, TAB):
        d.mkdir(parents=True, exist_ok=True)
    WARN, CAPTIONS = [], {}

    # ---------------------------------------------------------------- names, colours, styles
    SEL = ROOT / "analysis" / "nex_loss_selection.json"       # gate 1 (v7); older selection files are ignored
    SELREC = json.loads(SEL.read_text()) if SEL.exists() else {}
    _PREC = globals().get("PRECISION_ALL")
    if _PREC and SELREC and (SELREC.get("settings") or {}).get("precision") != _PREC:
        WARN.append(f"Gate-1 selection on file was made at another precision than {_PREC}; ignored until gate 1 is "
                    "decided again at this precision (STEP 5).")
        SELREC = {}
    MOTION_LOSS = SELREC.get("selected_loss")
    if MOTION_LOSS is None and SELREC.get("fallback_loss") and globals().get("ALLOW_MOTION_IF_NO_GAIN"):
        MOTION_LOSS = SELREC["fallback_loss"]
        WARN.append("GATE 1 NOT PASSED: NEX-ViP's auxiliary loss is a debugging fallback (ALLOW_MOTION_IF_NO_GAIN). "
                    "Do not report these results as the proposed method.")
    GATE1_PAPER_LOSS = bool(SELREC) and MOTION_LOSS is None and SELREC.get("applied_loss") == "l1_ssim"
    if GATE1_PAPER_LOSS:
        WARN.append("GATE 1 NOT PASSED: no auxiliary loss beat both the plain loss and copy-last-frame on validation, so "
                    "NEX-ViP is reported with its published L1+SSIM objective. Report the auxiliary-loss sweep "
                    "(tables/gate1_sweep.csv) as a negative result; do not claim the auxiliary loss helps.")
    if SELREC.get("plan_a"):             # every gate-1 candidate, validation only (seed 2024), for the paper / response letter
        _pr = SELREC.get("plain_reference") or {}
        _rows = [{"plan": "reference", "loss": "l1_ssim (published)", "weight": 0.0, **{k: _pr.get(k) for k in
                  ("val_skill_t1", "val_skill_th", "val_change_ratio", "collapsed")}, "failed": False}]
        _rows += [{"plan": r.get("plan"), "loss": r.get("loss"), "weight": r.get("weight"),
                   **{k: r.get(k) for k in ("val_skill_t1", "val_skill_th", "val_change_ratio", "collapsed")},
                   "failed": bool(r.get("failed"))} for r in (SELREC.get("plan_a") or []) + (SELREC.get("plan_b") or [])]
        _g = pd.DataFrame(_rows)
        _g["selected"] = _g.loss.eq(SELREC.get("selected_loss")) | (_g.plan.eq("reference") & GATE1_PAPER_LOSS)
        atomic_csv(TAB / "gate1_sweep.csv", _g)
    SELECTION_SEED_ = globals().get("SELECTION_SEED", 2024)
    _lsf = ROOT / "analysis" / "baseline_loss_selection.json"
    LOSS_CHOSEN = ({b: v["loss"] for b, v in json.loads(_lsf.read_text()).items()
                    if not _PREC or v.get("precision") == _PREC} if _lsf.exists() else {})   # same precision only
    ARCH_LABEL = {"nex_full": "NEX-ViP", "nex_identity": "NEX-ViP (identity transition)",
                  "predrnnpp": "PredRNN++†", "phydnet": "PhyDNet†", "simvpv2_gsta": "SimVP-gSTA†", "tau": "TAU†",
                  "persistence": "Persistence (copy last frame)",
                  "nex_frozen_encoder": "NEX-ViP (frozen random encoder)", "nex_direct": "NEX-ViP (direct decoder)",
                  "nex_aggregate": "NEX-ViP (learned context anchor)", "nex_direct_skip": "NEX-ViP (direct + gated skip)"}
    COLOR = {"nex_full": "#0072B2", "nex_identity": "#56B4E9", "predrnnpp": "#D55E00", "phydnet": "#009E73",
             "simvpv2_gsta": "#E69F00", "tau": "#CC79A7", "persistence": "#333333"}
    MARK = {"nex_full": "o", "nex_identity": "s", "predrnnpp": "^", "phydnet": "D", "simvpv2_gsta": "v",
            "tau": "P", "persistence": "x"}
    BASELINE_ARCH = list(globals().get("BASELINES", ["phydnet", "simvpv2_gsta", "tau"]))   # retrained, harmonized set
    PRECISION_USED = globals().get("PRECISION_ALL")     # only runs at this precision are reported (never mixed)
    FOOT = ("† trained with the shared objective (no native auxiliary losses); ‡ fails the sanity gate "
            "(worse than copying the last frame at t+1).")


    def arch(m):
        return m.split("__")[0]


    def label(m):
        a, parts = arch(m), m.split("__")[1:]
        out = ARCH_LABEL.get(a, a)
        extra = []
        for p in parts:
            if "_motion@" in p:
                extra.append(f"+ temporal-change loss, w={p.split('@')[1]}")
            elif "_tdiff@" in p:
                extra.append(f"+ temporal-difference loss, w={p.split('@')[1]}")
            elif p == "notselected":
                extra.append("not selected on validation")
            elif p == "l1_ssim":
                extra.append("L1+SSIM")
            elif p.startswith("lr"):
                extra.append(f"lr {p[2:]}")
            else:
                extra.append({"mse": "native MSE loss", "l1": "L1 only", "ssim": "SSIM only"}.get(p, p))
        if a.startswith("nex_") and not parts and MOTION_LOSS:
            extra.append("L1+SSIM only")
        if a in BASELINE_ARCH and not parts and LOSS_CHOSEN.get(a, "l1_ssim") != "l1_ssim":
            w_ = LOSS_CHOSEN[a].split("@")[1]
            extra.append(("+ temporal-change loss" if "_motion@" in LOSS_CHOSEN[a] else "+ temporal-difference loss") + f", w={w_}")
        if not extra:
            return out
        if out.endswith(")"):
            return out[:-1] + "; " + "; ".join(extra) + ")"
        return out + " (" + "; ".join(extra) + ")"


    def style(m):
        a = arch(m)
        if a == "persistence":
            ls = "--"
        elif "__lr" in m or "__mse" in m:   # learning-rate / native-loss checks
            ls = "-."
        elif a.startswith("nex_") and MOTION_LOSS and "_motion@" not in m and "_tdiff@" not in m:
            ls = ":"
        else:
            ls = "-"
        return dict(color=COLOR.get(a, "#777777"), marker=MARK.get(a, "o"), ls=ls)


    METRICS = [("mse", "MSE", "lower"), ("psnr", "PSNR (dB)", "higher"), ("ssim", "SSIM", "higher"),
               ("lpips", "LPIPS", "lower"), ("skill", "Skill vs copy", "higher"), ("foreground_mse", "Object MSE", "lower"),
               ("background_mse", "Background MSE", "lower"), ("object_crop_ssim", "Object-crop SSIM", "higher"),
               ("object_crop_lpips", "Object-crop LPIPS", "lower")]
    plt.rcParams.update({"font.size": 8, "axes.titlesize": 9, "axes.labelsize": 8, "legend.fontsize": 7,
                         "xtick.labelsize": 7, "ytick.labelsize": 7, "axes.spines.top": False,
                         "axes.spines.right": False, "axes.grid": True, "grid.color": "#e6e6e6",
                         "grid.linewidth": 0.6, "lines.linewidth": 1.6, "savefig.bbox": "tight",
                         "pdf.fonttype": 42, "ps.fonttype": 42})


    def save(fig, name):
        fig.savefig(FIG / f"{name}.pdf")
        fig.savefig(FIG / f"{name}.png", dpi=300)
        plt.show()
        plt.close(fig)


    # ---------------------------------------------------------------- 1. collect real evaluations (+ training protocol)
    splits = {}
    for p in (ROOT / "splits").glob("*.json"):
        try:
            m = json.loads(p.read_text())
            splits[m["id"]] = m
        except (ValueError, KeyError, TypeError):
            pass


    def split_name(sid):
        m = splits.get(sid, {})
        if m.get("dataset") == "kth":
            return "KTH (subject-disjoint)"
        if m.get("scheme") == "original_internal_split":
            return "CLEVRER original split"
        return f"CLEVRER random split {m.get('split_seed', sid)}"


    prov, frames, RUNS, _CSV = [], [], {}, {}
    EXCLUDED_PRECISION = []
    for marker in sorted((ROOT / "runs").glob("*/EVALUATED.json")):
        run = marker.parent
        cfg = json.loads((run / "config.json").read_text())
        if PRECISION_USED and cfg.get("precision", "fp32") != PRECISION_USED:
            EXCLUDED_PRECISION.append(run.name)
            continue
        if cfg["name"] not in BASELINE_ARCH and not cfg["name"].startswith("nex_"):
            continue                        # e.g. PredRNN++ runs from earlier versions (not retrained in v7)
        for role, path in json.loads(marker.read_text()).items():
            path = Path(path)
            if not path.exists() and "evaluation" in path.parts:     # package / moved Drive: resolve under ROOT
                path = ROOT / Path(*path.parts[path.parts.index("evaluation"):])
            folder = path.parent
            if not (path.exists() and (folder / "DONE.json").exists() and (folder / "spec.json").exists()):
                WARN.append(f"Missing/incomplete evaluation file skipped: {path}")
                continue
            spec = json.loads((folder / "spec.json").read_text())
            if spec.get("pilot_limit") is not None:
                continue
            if str(path) not in _CSV:
                _CSV[str(path)] = pd.read_csv(path)
            f = _CSV[str(path)].copy()
            f["evaluation_id"] = folder.name
            f["eval_mtime"] = (folder / "DONE.json").stat().st_mtime
            f["train_windows"] = -1 if role == "persistence" else cfg.get("windows", 3)
            f["run_id"] = "" if role == "persistence" else run.name
            frames.append(f)
            if role != "persistence":
                RUNS[(spec["model"], spec["seed"], spec["split"], cfg.get("windows", 3))] = run
            prov.append({"run_id": run.name, "role": role, "model": spec["model"], "seed": spec["seed"],
                         "split": spec["split"], "evaluation_id": folder.name, "rows": len(f),
                         "checkpoint_sha256": spec["checkpoint"], "windows_per_video_eval": spec["windows"],
                         "train_windows": cfg.get("windows", 3), "lr": cfg.get("lr"), "trained_model": cfg["name"],
                         "loss": cfg["loss"]})
    if EXCLUDED_PRECISION:
        WARN.append(f"{len(EXCLUDED_PRECISION)} evaluated run(s) trained at another precision than {PRECISION_USED} "
                    "(earlier notebook versions) are excluded, so every reported model uses the same training precision.")
    if not frames:
        raise RuntimeError("No completed evaluations yet. Finish at least one job with STEP 5; "
                           "this cell never fabricates results.")
    PROV = pd.DataFrame(prov).drop_duplicates(["model", "seed", "split", "evaluation_id"])
    atomic_csv(TAB / "provenance.csv", PROV)
    ALL = pd.concat(frames, ignore_index=True)
    ALL = ALL[~ALL["pilot"].astype(bool)]

    # Baselines: the learning rate AND loss chosen on CLEVRER validation define the reported model ("tau", …); the
    # other candidates stay visible as "…, not selected on validation" in the baseline-check table only.
    _lrf = ROOT / "analysis" / "baseline_lr_selection.json"
    LR_CHOSEN = ({b: v["lr"] for b, v in json.loads(_lrf.read_text()).items()
                  if not _PREC or v.get("precision") == _PREC} if _lrf.exists() else {})     # same precision only


    def remap_cfg(m):
        a = arch(m)
        if a not in LR_CHOSEN:
            return m
        parts = m.split("__")[1:]
        lrp = [p for p in parts if p.startswith("lr")]
        lr = float(lrp[0][2:]) if lrp else 2e-4
        loss = next((p for p in parts if not p.startswith("lr")), "l1_ssim")
        lr_ok, chosen = math.isclose(lr, LR_CHOSEN[a]), LOSS_CHOSEN.get(a)
        if lr_ok and (loss == chosen or (chosen is None and loss == "l1_ssim")):
            return a
        if lr_ok and loss == "mse":
            return f"{a}__mse"                       # native-loss check at the chosen lr
        return "__".join([a, loss, f"lr{lr:g}", "notselected"])


    if LR_CHOSEN:
        ALL["model"] = ALL.model.map(remap_cfg)
        RUNS = {(remap_cfg(k[0]),) + tuple(k[1:]): v for k, v in RUNS.items()}
        PROV["model"] = PROV.model.map(remap_cfg)
    is_check = lambda m: "notselected" in m

    # The final NEX-ViP's run on the selection seed is the run gate 1 chose on validation: reported separately
    # (sensitivity table), never in the headline numbers, so the selection cannot bias them.
    orig_split = next((sid for sid, s_ in splits.items() if s_.get("scheme") == "original_internal_split"), None)
    SELECTION_ROWS = pd.DataFrame()
    if MOTION_LOSS or GATE1_PAPER_LOSS:   # the selected run AND the plain reference of gate 1 (selection-seed runs)
        _sel = (ALL.model.isin([m for m in (f"nex_full__{MOTION_LOSS}" if MOTION_LOSS else None, "nex_full") if m])
                & ALL.seed.eq(SELECTION_SEED_)
                & ALL.split.eq(orig_split))
        SELECTION_ROWS, ALL = ALL[_sel].copy(), ALL[~_sel]
        if len(SELECTION_ROWS):
            WARN.append(f"Gate-1 runs on the selection seed ({SELECTION_SEED_}; final NEX-ViP and its plain-loss reference, CLEVRER "
                        "original split) excluded from headline results; shown in tables/selection_seed_sensitivity.csv.")

    # KTH protocol: report the larger training budget when it exists; never pool two protocols.
    KTH_WIN_USED, KTH_PROTOCOL = None, None
    is_kth = ALL.dataset.eq("kth") & ALL.model.ne("persistence")
    if is_kth.any():
        new = ALL[is_kth & ALL.train_windows.eq(KTH_TRAIN_WINDOWS)]
        old_models = set(ALL[is_kth & ALL.train_windows.ne(KTH_TRAIN_WINDOWS)].model)
        if len(new):
            ALL = ALL[~(is_kth & ALL.train_windows.ne(KTH_TRAIN_WINDOWS))]
            if old_models - set(new.model):
                WARN.append("KTH: models only available with the old 3-window budget are omitted: "
                            + ", ".join(sorted(old_models - set(new.model))))
            KTH_PROTOCOL = f"{KTH_TRAIN_WINDOWS} training windows/video/epoch"
            KTH_WIN_USED = KTH_TRAIN_WINDOWS
        else:
            KTH_WIN_USED = 3
            KTH_PROTOCOL = "3 training windows/video/epoch (old budget)"
            WARN.append("KTH results use the OLD 3-window training budget (≈540 updates); run the v6 KTH phase.")
    key = ["dataset", "split", "model", "seed", "video", "start", "horizon"]
    dup = ALL.duplicated(key, keep=False)
    if dup.any():
        _g = ALL[dup].groupby(key)[["mse", "ssim", "lpips"]]
        spread = float(np.nanmax((_g.max() - _g.min()).to_numpy()))
        atomic_csv(TAB / "duplicate_evaluations.csv", ALL[dup][key + ["evaluation_id", "eval_mtime"]].drop_duplicates(
            ["model", "seed", "split", "evaluation_id"]))
        if spread > 1e-5:
            WARN.append(f"Same model/seed/video evaluated more than once with different values (max diff {spread:.2e}); "
                        "the most recent evaluation was kept.")
        ALL = ALL.sort_values("eval_mtime").drop_duplicates(key, keep="last")
    ALL["psnr"] = 10 * np.log10(1.0 / ALL["mse"].clip(lower=1e-10))
    ALL["split_name"] = ALL["split"].map(split_name)

    # Skill vs persistence, paired on the same held-out windows: 1 − ΣMSE(model) / ΣMSE(copy last frame)
    PERS = (ALL[ALL.model == "persistence"].drop_duplicates(["split", "video", "start", "horizon"])
            [["split", "video", "start", "horizon", "mse"]].rename(columns={"mse": "mse_persistence"}))
    ALL = ALL.merge(PERS, on=["split", "video", "start", "horizon"], how="left")
    if ALL.mse_persistence.isna().any():
        WARN.append("Some windows lack a persistence evaluation; skill is computed on the paired windows only.")

    # coverage check against the frozen manifest
    cov = []
    for (ds, sp, mod, seed), g in ALL.groupby(["dataset", "split", "model", "seed"]):
        expected = len(splits[sp]["eval"]) if sp in splits else np.nan
        got = g["video"].nunique()
        cov.append({"dataset": ds, "split": split_name(sp), "model": mod, "seed": seed, "videos": got,
                    "expected_videos": expected, "complete": got == expected,
                    "windows": len(g[["video", "start"]].drop_duplicates())})
    COV = pd.DataFrame(cov)
    atomic_csv(TAB / "coverage.csv", COV)
    if not COV["complete"].all():
        WARN.append("Some evaluations do not cover every held-out video: " +
                    "; ".join(f"{r.model} seed {r.seed}" for r in COV[~COV.complete].itertuples()))

    # ---------------------------------------------------------------- 2. summaries (windows -> video -> seed)
    BASE_COLS = [m[0] for m in METRICS if m[0] != "skill" and m[0] in ALL.columns and ALL[m[0]].notna().any()]
    VID = ALL.groupby(["dataset", "split", "split_name", "model", "seed", "video", "horizon"])[BASE_COLS].mean().reset_index()
    SEED = VID.groupby(["dataset", "split", "split_name", "model", "seed", "horizon"])[BASE_COLS].mean().reset_index()
    paired = ALL.dropna(subset=["mse_persistence"])
    SK = (paired.groupby(["dataset", "split", "split_name", "model", "seed", "horizon"])[["mse", "mse_persistence"]]
          .sum().reset_index())
    SK["skill"] = 1 - SK["mse"] / SK["mse_persistence"]
    SEED = SEED.merge(SK[["dataset", "split", "model", "seed", "horizon", "skill"]],
                      on=["dataset", "split", "model", "seed", "horizon"], how="left")
    METRICS = [m for m in METRICS if m[0] in SEED.columns and SEED[m[0]].notna().any()]
    MCOLS = [m[0] for m in METRICS]
    SUMM = SEED.groupby(["dataset", "split", "split_name", "model", "horizon"])[MCOLS].agg(["mean", "std", "count"])
    SUMM.columns = [f"{a}_{b}" for a, b in SUMM.columns]
    SUMM = SUMM.reset_index()
    atomic_csv(TAB / "per_seed_metrics.csv", SEED)
    atomic_csv(TAB / "summary_all_horizons.csv", SUMM)

    # ---------------------------------------------------------------- 3. sanity gate + collapse detector
    diag_rows = []
    for (mod, seed, sp, win), run in RUNS.items():
        if sp not in set(ALL.split):
            continue
        if splits.get(sp, {}).get("dataset") == "kth" and win != KTH_WIN_USED:
            continue
        d = None
        if "run_diagnostics" in globals():
            try:
                d = run_diagnostics(run) if MEASURE_OLD_RUN_DIAGNOSTICS else None
            except Exception as e:  # diagnostics are optional; never block the report
                WARN.append(f"Diagnostics unavailable for {mod} seed {seed}: {type(e).__name__}: {e}")
        t1 = SEED[(SEED.model == mod) & (SEED.seed == seed) & (SEED.split == sp) & (SEED.horizon == 1)]
        diag_rows.append({"split_name": split_name(sp), "model": mod, "seed": seed, "train_windows": win,
                          "test_skill_t1": float(t1.skill.iloc[0]) if len(t1) else np.nan,
                          "val_skill_t1": (d or {}).get("val_skill_t1"), "val_skill_t10": (d or {}).get("val_skill_th"),
                          "val_change_ratio": (d or {}).get("val_change_ratio"),
                          "collapsed": (d or {}).get("collapsed"), "run_id": run.name})
    DIAG = pd.DataFrame(diag_rows)
    GATE_FAIL, COLLAPSED = set(), {}
    if len(DIAG):
        DIAG = DIAG.sort_values(["split_name", "model", "seed"])
        atomic_csv(TAB / "run_diagnostics.csv", DIAG)
        for (spn, mod), g in DIAG.groupby(["split_name", "model"]):
            if (g.test_skill_t1 <= 0).any():
                GATE_FAIL.add((spn, mod))
            n_col = int(g.collapsed.fillna(False).astype(bool).sum())
            if n_col:
                COLLAPSED[(spn, mod)] = f"{n_col}/{len(g)}"
        print("\nSanity gate (test skill vs copy-last-frame at t+1 must be > 0) and collapse detector "
              "(validation change ratio < 0.10 ⇒ collapsed):")
        display(DIAG.drop(columns=["run_id"]))
        for spn, mod in sorted(GATE_FAIL):
            WARN.append(f"{spn}: {label(mod)} fails the sanity gate (worse than copying at t+1 in ≥1 seed) — "
                        "undertrained/misconfigured; marked ‡ and must not be presented as a tuned model.")
        for (spn, mod), frac in sorted(COLLAPSED.items()):
            WARN.append(f"{spn}: {label(mod)} collapsed to copy-last-frame in {frac} seeds (validation change ratio < 0.10).")

    # ---------------------------------------------------------------- 4. reference model and display sets
    motion_ref = f"nex_full__{MOTION_LOSS}" if MOTION_LOSS else None
    seeds_of = lambda m, sp: set(SEED[(SEED.model == m) & (SEED.split == sp)].seed)
    REFERENCE = motion_ref if motion_ref and len(seeds_of(motion_ref, orig_split)) >= 3 else "nex_full"
    if motion_ref and REFERENCE != motion_ref:
        WARN.append(f"Reference is still the plain NEX-ViP: {label(motion_ref)} has <3 evaluated seeds on the original split.")


    def principal(models):
        first = [REFERENCE] + [m for m in ("nex_full", motion_ref, f"nex_identity__{MOTION_LOSS}" if MOTION_LOSS else None,
                                           "nex_identity") if m and m != REFERENCE]
        rest = [m for m in BASELINE_ARCH] + ["persistence"]
        return [m for m in first + rest if m in models]


    def order(models):
        p = principal(models)
        return p + sorted(m for m in models if m not in p)


    def shown(m, spn):
        return label(m) + ("‡" if (spn, m) in GATE_FAIL else "")


    def ci95(sd, n):
        return st.t.ppf(0.975, n - 1) * sd / np.sqrt(n) if n > 1 else np.nan


    def results_table(df, models, h, spn):
        rows = []
        for mod in models:
            r = df[(df.model == mod) & (df.horizon == h)]
            if r.empty:
                continue
            row = {"Model": shown(mod, spn), "Seeds": int(r[f"{MCOLS[0]}_count"].iloc[0]),
                   "Collapsed seeds": "—" if mod == "persistence" else COLLAPSED.get((spn, mod), "0" if len(DIAG) else "n/a")}
            for c, name, better in METRICS:
                row[f"{name} {'↓' if better == 'lower' else '↑'}"] = (r[f"{c}_mean"].iloc[0], r[f"{c}_std"].iloc[0])
            rows.append(row)
        return rows


    def fmt_tables(rows, stem, title, sig_best=None):
        if not rows:
            return
        cols = [c for c in rows[0] if c not in ("Model", "Seeds", "Collapsed seeds")]
        plain, latex = [], []
        for r in rows:
            p = {"Model": r["Model"], "Seeds": r["Seeds"], "Collapsed seeds": r["Collapsed seeds"]}
            l = {"Model": r["Model"].replace("†", "$^\\dagger$").replace("‡", "$^\\ddagger$"), "Seeds": r["Seeds"],
                 "Collapsed": r["Collapsed seeds"]}
            for c in cols:
                mu, sd = r[c]
                d = 2 if c.startswith("PSNR") else (3 if c.startswith("Skill") else 4)
                s = "n/a" if not np.isfinite(mu) else (f"{mu:.{d}f}" if not np.isfinite(sd) else f"{mu:.{d}f} ± {sd:.{d}f}")
                p[c] = s
                l[c] = ("\\textbf{" + s + "}") if sig_best and (r["Model"], c) in sig_best else s
            plain.append(p)
            latex.append(l)
        P = pd.DataFrame(plain)
        atomic_csv(TAB / f"{stem}.csv", P)
        (TAB / f"{stem}.tex").write_text(
            f"% {title}. Mean ± s.d. across training seeds (each seed averaged over all held-out videos).\n"
            "% Skill vs copy = 1 − MSE(model)/MSE(copy last frame) on the same windows (>0: better than copying).\n"
            "% Bold = better than every other row with a 95% CI excluding zero in the seed-level comparison (see paired file).\n"
            "% " + FOOT + "\n"
            + pd.DataFrame(latex).to_latex(index=False, escape=False).replace("±", "$\\pm$")
            .replace("↓", "$\\downarrow$").replace("↑", "$\\uparrow$"))
        print("\n" + title)
        display(P)


    # ---------------------------------------------------------------- 5. seed-level statistics vs the reference
    PRIMARY_METRIC = "mse"     # pre-declared primary endpoint (t+MAIN_H); other metrics are secondary
    CLAIMED_ABL = set(globals().get("CLAIMED_ABLATIONS", ["nex_direct", "nex_direct_skip"]))


    def in_family(c, reference):
        """Pre-declared comparison family for Holm: chosen-config baselines, same-loss identity transition and
        claimed ablations, and the plain-loss NEX-ViP (tests the auxiliary loss)."""
        a, suffix = arch(c), reference[len(arch(reference)):]
        if c in BASELINE_ARCH:
            return True
        if a == "nex_identity" or a in CLAIMED_ABL:
            return c == a + suffix
        return c == "nex_full" and reference != "nex_full"


    def declared_members(reference, ablations=True):
        suffix = reference[len(arch(reference)):]
        out = list(BASELINE_ARCH) + ["nex_identity" + suffix]
        out += [a + suffix for a in sorted(CLAIMED_ABL) if suffix and ablations]   # ablations: original split only
        return out + (["nex_full"] if reference != "nex_full" else [])

    def seed_level_effects(g, reference, metrics, repeats=4000, declared=None):
        """Differences of seed means (reference − comparator) on shared videos, all evaluated seeds of each model.
        Primary interval and test: Welch t on per-seed means (training seeds are the independent replicates;
        videos are not), Welch–Satterthwaite df. Secondary: 95% bootstrap CI resampling seeds and videos jointly
        (can under-cover with 3–5 seeds). Effect size: Hedges' g. Holm correction within a pre-declared family
        (see FAMILY): each baseline at its chosen configuration, the identity-transition and claimed ablations
        (same loss), and the plain-loss NEX-ViP; one family per metric and split; MSE is the primary metric."""
        out = []
        vm = g.groupby(["model", "seed", "video"])[metrics].mean().reset_index()
        for other in sorted(set(vm.model) - {reference}):
            SA = sorted(set(vm[vm.model == reference].seed))
            SB = sorted(set(vm[vm.model == other].seed))
            V = sorted(set(vm[vm.model == reference].video) & set(vm[vm.model == other].video))
            if min(len(SA), len(SB)) < 3 or len(V) < 2:
                WARN.append(f"{other}: fewer than 3 evaluated seeds; no test reported.")
                continue
            for met in metrics:
                a = vm[vm.model == reference].pivot(index="seed", columns="video", values=met).reindex(index=SA, columns=V)
                b = vm[vm.model == other].pivot(index="seed", columns="video", values=met).reindex(index=SB, columns=V)
                ok = np.isfinite(a.to_numpy()).all(0) & np.isfinite(b.to_numpy()).all(0)
                A, B = a.to_numpy()[:, ok], b.to_numpy()[:, ok]
                if A.shape[1] < 2:
                    continue
                rng = np.random.default_rng(317)
                boot = np.empty(repeats)
                for i in range(repeats):
                    si, sj = rng.integers(len(SA), size=len(SA)), rng.integers(len(SB), size=len(SB))
                    vi = rng.integers(A.shape[1], size=A.shape[1])
                    boot[i] = A[np.ix_(si, vi)].mean() - B[np.ix_(sj, vi)].mean()
                ma, mb = A.mean(1), B.mean(1)
                diff = ma.mean() - mb.mean()
                sp_ = np.sqrt(((len(ma) - 1) * ma.var(ddof=1) + (len(mb) - 1) * mb.var(ddof=1)) / (len(ma) + len(mb) - 2))
                hedges = diff / sp_ * (1 - 3 / (4 * (len(ma) + len(mb)) - 9)) if sp_ > 0 else np.nan
                va, vb = ma.var(ddof=1) / len(ma), mb.var(ddof=1) / len(mb)
                if va + vb > 0:
                    df_w = (va + vb) ** 2 / (va ** 2 / (len(ma) - 1) + vb ** 2 / (len(mb) - 1))
                    half = st.t.ppf(0.975, df_w) * np.sqrt(va + vb)
                    p_seed = float(st.ttest_ind(ma, mb, equal_var=False).pvalue)
                else:
                    df_w, half, p_seed = np.nan, np.nan, np.nan
                pv = A.mean(0) - B.mean(0)
                p_vid = 1.0 if np.all(pv == 0) else float(st.wilcoxon(pv).pvalue)
                better_low = met not in ("ssim", "psnr", "skill", "object_crop_ssim")
                out.append({"comparator": other, "metric": met, "difference_reference_minus_other": diff,
                            "ci_low": diff - half, "ci_high": diff + half, "welch_df": df_w,
                            "boot_ci_low": float(np.quantile(boot, 0.025)), "boot_ci_high": float(np.quantile(boot, 0.975)),
                            "hedges_g_seed": hedges, "p_seed_welch": p_seed, "p_video_wilcoxon_conditional": p_vid,
                            "reference_better": bool(diff < 0 if better_low else diff > 0),
                            "seeds": f"{len(SA)} vs {len(SB)}", "paired_videos": int(A.shape[1])})
        E = pd.DataFrame(out)
        if len(E):
            E["family"] = E.comparator.map(lambda c: in_family(c, reference))
            E["p_seed_holm"] = np.nan
            members = declared if declared is not None else declared_members(reference)
            m_decl = len(members)
            present = set(E[E.family].comparator)
            missing = sorted(set(members) - present)
            if missing:
                WARN.append(f"Holm family incomplete for {label(reference)} (missing: {', '.join(missing)}); corrected for the "
                            f"declared family size m={m_decl}, so p-values are conservative until those runs finish.")
            for met in set(E.metric):
                sel_ = E.index[(E.metric == met) & E.family & E.p_seed_welch.notna()]
                p = E.loc[sel_, "p_seed_welch"].to_numpy()
                if len(p):
                    m_ = max(m_decl, len(p))
                    ix = np.argsort(p)
                    adj = np.minimum(1, np.maximum.accumulate(p[ix] * (m_ - np.arange(len(p)))))
                    E.loc[sel_[ix], "p_seed_holm"] = adj
            E["ci_excludes_zero"] = (E.ci_low > 0) | (E.ci_high < 0)
            E["primary"] = E.metric.eq(PRIMARY_METRIC)
        return E


    EFFECTS = []
    for (ds, sp), g in ALL[ALL.horizon == MAIN_H].groupby(["dataset", "split"]):
        if REFERENCE not in set(g.model):
            continue
        mets = [m for m in ("mse", "ssim", "lpips", "foreground_mse") if m in g and g[m].notna().any()]
        e = seed_level_effects(g, REFERENCE, mets, declared=declared_members(REFERENCE, ablations=(sp == orig_split)))
        if len(e):
            e["split_name"] = split_name(sp)
            EFFECTS.append(e)
    EFFECTS = pd.concat(EFFECTS, ignore_index=True) if EFFECTS else pd.DataFrame()
    if len(EFFECTS):
        atomic_csv(TAB / f"seed_level_effects_t{MAIN_H}.csv", EFFECTS)
        print(f"\nDifferences ({label(REFERENCE)} − comparator) at t+{MAIN_H}. 95% CI and p: Welch t on per-seed means "
              f"(seeds = independent replicates); Holm within the pre-declared family per metric and split "
              f"(primary metric: {PRIMARY_METRIC}); bootstrap CI over seeds × videos in the CSV (secondary).")
        display(EFFECTS[["split_name", "comparator", "metric", "difference_reference_minus_other", "ci_low", "ci_high",
                         "hedges_g_seed", "p_seed_holm", "family", "seeds", "paired_videos"]])

    # main + ablation tables (bold only where the reference is reliably better / comparator reliably better)
    for (ds, sp, spn), g in SUMM.groupby(["dataset", "split", "split_name"]):
        tag = f"{ds}_{sp}"
        sig = set()
        if len(EFFECTS):
            e = EFFECTS[EFFECTS.split_name == spn]
            names = {c: n for c, n, _ in METRICS}
            arrows = {c: "↓" if b == "lower" else "↑" for c, _, b in METRICS}
            for met in set(e.metric):
                em = e[(e.metric == met) & e.family]
                if len(em) and (em.ci_excludes_zero & em.reference_better & em.p_seed_holm.lt(0.05)).all():
                    sig.add((shown(REFERENCE, spn), f"{names[met]} {arrows[met]}"))
        title_extra = f", KTH protocol: {KTH_PROTOCOL}" if ds == "kth" else ""
        fmt_tables(results_table(g, principal(set(g.model)), MAIN_H, spn), f"main_table_t{MAIN_H}_{tag}",
                   f"Main results, {spn}, t+{MAIN_H}{title_extra}", sig)
        abl = [m for m in order(set(g.model)) if arch(m).startswith("nex_") or m == "persistence"]
        if len(abl) > 3:
            fmt_tables(results_table(g, abl, MAIN_H, spn), f"ablation_table_t{MAIN_H}_{tag}",
                       f"NEX-ViP ablations, {spn}, t+{MAIN_H}")
        extra = [m for m in order(set(g.model)) if arch(m) in BASELINE_ARCH and "__" in m]
        if extra:
            fmt_tables(results_table(g, [m for m in order(set(g.model)) if arch(m) in {arch(x) for x in extra}],
                                     MAIN_H, spn), f"baseline_checks_t{MAIN_H}_{tag}",
                       f"Baseline checks (learning-rate candidate not selected, native MSE loss, same auxiliary loss), {spn}")
    print("\nNote on 'accuracy': video prediction has no class accuracy. Quality is MSE/PSNR (pixel error), SSIM "
          "(structure), LPIPS (perceptual distance) and skill vs copying the last frame, plus object-region metrics.")

    handles = lambda models, spn="": [Line2D([0], [0], color=style(m)["color"], marker=style(m)["marker"],
                                             ls=style(m)["ls"], label=shown(m, spn)) for m in models]

    # ---------------------------------------------------------------- 5b. failure analysis (where does each model fail?)
    # Windows are grouped by how much the scene changes: the error of copying the last frame (persistence MSE at
    # t+MAIN_H) splits held-out windows into low / medium / high-motion terciles. Skill is computed per seed within
    # each tercile; mean ± 95% CI across seeds. Worst cases: the held-out videos where the reference model loses most
    # to copying the last frame (mean over seeds), so failure examples are not hand-picked.
    FAIL_ROWS, WORST = [], []
    for (ds, sp, spn), g in ALL[(ALL.horizon == MAIN_H) & ALL.mse_persistence.notna()].groupby(["dataset", "split", "split_name"]):
        pw = g[g.model == "persistence"].drop_duplicates(["video", "start"])
        if len(pw) < 6:
            continue
        terc = pd.qcut(pw.mse_persistence.rank(method="first"), 3, labels=["low", "medium", "high"])
        g = g.merge(pw[["video", "start"]].assign(motion=terc.to_numpy()), on=["video", "start"], how="inner")
        for (mod, tert), gg in g[g.model.isin(principal(set(g.model)))].groupby(["model", "motion"], observed=True):  # noqa
            per_seed = gg.groupby("seed").apply(lambda d: 1 - d.mse.sum() / d.mse_persistence.sum())
            n = len(per_seed)
            FAIL_ROWS.append({"split_name": spn, "model": mod, "motion_tercile": tert, "seeds": n,
                              "skill_mean": per_seed.mean(), "skill_ci95": ci95(per_seed.std(ddof=1), n) if n > 1 else np.nan,
                              "windows": gg[["video", "start"]].drop_duplicates().shape[0]})
        ref = g[g.model == REFERENCE]
        if len(ref):
            pv = ref.groupby("video").apply(lambda d: pd.Series({"skill": 1 - d.mse.sum() / d.mse_persistence.sum(),
                                                                 "copy_mse": d.mse_persistence.mean()}))
            pv = pv.sort_values("skill")
            for v, r in pv.head(5).iterrows():
                WORST.append({"split_name": spn, "model": REFERENCE, "video": v, "skill_vs_copy": r.skill,
                              "copy_mse (motion proxy)": r.copy_mse})
            WARN.append(f"{spn}: {label(REFERENCE)} is worse than copying the last frame on "
                        f"{(pv.skill < 0).mean():.0%} of held-out videos at t+{MAIN_H} (seed-averaged).")
    if FAIL_ROWS:
        FAIL = pd.DataFrame(FAIL_ROWS)
        atomic_csv(TAB / f"failure_skill_by_motion_t{MAIN_H}.csv", FAIL)
        atomic_csv(TAB / f"failure_worst_videos_t{MAIN_H}.csv", pd.DataFrame(WORST))
        print(f"\nFailure analysis: skill vs copy-last-frame by motion tercile at t+{MAIN_H} (mean ± 95% CI across seeds)")
        display(FAIL)
        for (ds, sp, spn), g in SUMM.groupby(["dataset", "split", "split_name"]):
            f = FAIL[FAIL.split_name == spn]
            if f.empty:
                continue
            models = [m for m in principal(set(f.model))]
            fig, ax = plt.subplots(figsize=(3.6, 2.4))
            xs = {"low": 0, "medium": 1, "high": 2}
            w = 0.8 / max(1, len(models))
            for i, m in enumerate(models):
                r = f[f.model == m].set_index("motion_tercile").reindex(["low", "medium", "high"])
                s_ = style(m)
                ax.errorbar(np.arange(3) - 0.4 + w * (i + 0.5), r.skill_mean, yerr=r.skill_ci95, fmt=s_["marker"],
                            color=s_["color"], ms=4, capsize=2, lw=1)
            ax.axhline(0, color="#333", lw=0.8, ls="--")
            ax.set_xticks(range(3), ["low motion", "medium", "high motion"])
            ax.set_ylabel(f"Skill vs copy at t+{MAIN_H} (↑)")
            ax.set_title(f"{spn}: where models fail", fontsize=8)
            fig.legend(handles=handles(models, spn), loc="lower center", ncol=2, bbox_to_anchor=(0.5, -0.35), frameon=False)
            name = f"fig9_failure_by_motion_{ds}_{sp}"
            CAPTIONS[name] = (f"Skill vs copying the last frame at t+{MAIN_H}, held-out windows split into terciles of scene "
                              "change (persistence MSE). Markers: mean across training seeds; bars: 95% CI (t, across seeds). "
                              "Below the dashed line the model is worse than copying the last frame. " + FOOT)
            save(fig, name)

    # ---------------------------------------------------------------- 6. figures

    # Fig 1: quality vs forecast horizon
    for (ds, sp, spn), g in SUMM.groupby(["dataset", "split", "split_name"]):
        models = principal(set(g.model))
        panels = [m for m in METRICS if m[0] in ("mse", "ssim", "lpips")]
        fig, axes = plt.subplots(1, len(panels), figsize=(7.2, 2.2))
        for ax, (c, name, better) in zip(np.atleast_1d(axes), panels):
            for m in models:
                r = g[g.model == m].sort_values("horizon")
                x, mu, sd = r.horizon.to_numpy(), r[f"{c}_mean"].to_numpy(), r[f"{c}_std"].fillna(0).to_numpy()
                s = style(m)
                ax.plot(x, mu, color=s["color"], marker=s["marker"], ls=s["ls"], ms=4)
                lo = np.maximum(mu - sd, 0) if c in ("mse", "lpips") else mu - sd
                hi = np.minimum(mu + sd, 1) if c == "ssim" else mu + sd
                ax.fill_between(x, lo, hi, color=s["color"], alpha=0.12, lw=0)
            ax.axvspan(MAIN_H + 0.5, 31, color="#f2f2f2", zorder=0, lw=0)
            ax.set_xticks([1, 5, 10, 20, 30])
            ax.set_xlabel("Forecast horizon (frames)")
            ax.set_title(f"{name} ({'↓' if better == 'lower' else '↑'})")
        fig.legend(handles=handles(models, spn), loc="lower center", ncol=3, bbox_to_anchor=(0.5, -0.32), frameon=False)
        fig.suptitle(f"{spn}: prediction quality vs forecast horizon", fontsize=9, y=1.06)
        fig.text(0.5, -0.40, FOOT, ha="center", fontsize=6.5, color="#555")
        name = f"fig1_quality_vs_horizon_{ds}_{sp}"
        CAPTIONS[name] = (f"Prediction quality vs horizon on held-out videos ({spn}). Lines: mean over training seeds "
                          f"(each seed averaged over all held-out videos); bands: ±1 s.d. across seeds. Grey: beyond the "
                          f"{MAIN_H}-frame training horizon (autoregressive rollout). " + FOOT)
        save(fig, name)

    # Fig 8: skill vs copy-last-frame (the trivial baseline) per horizon, 95% CI across seeds
    for (ds, sp, spn), g in SUMM.groupby(["dataset", "split", "split_name"]):
        if "skill_mean" not in g:
            continue
        models = [m for m in principal(set(g.model)) if m != "persistence"]
        fig, ax = plt.subplots(figsize=(3.6, 2.6))
        for m in models:
            r = g[g.model == m].sort_values("horizon")
            mu, n = r.skill_mean.to_numpy(), r.skill_count.to_numpy()
            half = np.array([ci95(s, k) for s, k in zip(r.skill_std.fillna(0), n)])
            s = style(m)
            ax.plot(r.horizon, mu, color=s["color"], marker=s["marker"], ls=s["ls"], ms=4)
            ax.fill_between(r.horizon, mu - np.nan_to_num(half), mu + np.nan_to_num(half), color=s["color"], alpha=0.12, lw=0)
        ax.axhline(0, color="#333", lw=0.9, ls="--")
        ax.text(30, 0, " copy last frame", va="bottom", ha="right", fontsize=6.5, color="#333")
        ax.axvspan(MAIN_H + 0.5, 31, color="#f2f2f2", zorder=0, lw=0)
        ax.set_xticks([1, 5, 10, 20, 30])
        ax.set_xlabel("Forecast horizon (frames)")
        ax.set_ylabel("Skill = 1 − MSE / MSE(copy)  (↑)")
        ax.set_title(f"{spn}: skill vs copying the last frame")
        fig.legend(handles=handles(models, spn), loc="lower center", ncol=2, bbox_to_anchor=(0.5, -0.42), frameon=False)
        name = f"fig8_skill_vs_persistence_{ds}_{sp}"
        CAPTIONS[name] = (f"Skill relative to copying the last observed frame, 1 − ΣMSE(model)/ΣMSE(copy) on identical "
                          f"held-out windows ({spn}). Above 0 = better than copying. Bands: 95% t-interval across "
                          "training seeds. " + FOOT)
        save(fig, name)

    # Fig 2: seed-level differences (forest plot)
    if len(EFFECTS):
        for spn, g in EFFECTS.groupby("split_name"):
            mets = [m for m in ("mse", "ssim", "lpips") if m in set(g.metric)]
            comps = order(set(g.comparator))
            fig, axes = plt.subplots(1, len(mets), figsize=(7.2, 0.42 * len(comps) + 1.3), sharey=True)
            for ax, met in zip(np.atleast_1d(axes), mets):
                better = dict((c, b) for c, _, b in METRICS)[met]
                for i, cmp_ in enumerate(comps):
                    r = g[(g.metric == met) & (g.comparator == cmp_)]
                    if r.empty:
                        continue
                    r = r.iloc[0]
                    s = style(cmp_)
                    ax.errorbar(r.difference_reference_minus_other, i,
                                xerr=[[r.difference_reference_minus_other - r.ci_low], [r.ci_high - r.difference_reference_minus_other]],
                                fmt=s["marker"], color=s["color"], mfc=s["color"] if r.ci_excludes_zero else "white", ms=5, capsize=2,
                                alpha=1.0 if r.ci_excludes_zero else 0.5)
                ax.axvline(0, color="#333", lw=0.8)
                ax.set_yticks(range(len(comps)), [shown(c, spn) for c in comps])
                ax.invert_yaxis()
                ax.set_title(f"Δ{dict((c, n) for c, n, _ in METRICS)[met]}  ({'← reference better' if better == 'lower' else 'reference better →'})")
                ax.set_xlabel("reference − comparator")
            fig.suptitle(f"{spn}: {label(REFERENCE)} vs each comparator at t+{MAIN_H}", fontsize=9, y=1.08)
            fig.text(0.5, -0.17, FOOT, ha="center", fontsize=6.5, color="#555")
            name = f"fig2_seed_level_differences_t{MAIN_H}_{spn.replace(' ', '_')}"
            CAPTIONS[name] = (f"Difference of seed means ({label(REFERENCE)} minus comparator) at t+{MAIN_H}, {spn}. Error bars: "
                              "95% bootstrap CI resampling training seeds and videos. Solid filled marker: CI excludes zero; faded: CI includes zero. " + FOOT)
            save(fig, name)

    # Fig 3: validation curves. (a) training objective for L1+SSIM runs; (b) validation skill (comparable across losses)
    hist = []
    for run in (ROOT / "runs").glob("*"):
        if not ((run / "config.json").exists() and (run / "history.csv").exists()):
            continue
        cfg = json.loads((run / "config.json").read_text())
        if cfg["name"] not in ARCH_LABEL or (cfg["name"] not in BASELINE_ARCH and not cfg["name"].startswith("nex_")):
            continue
        if PRECISION_USED and cfg.get("precision", "fp32") != PRECISION_USED:
            continue                         # same precision filter as the tables (never mixed)
        h = pd.read_csv(run / "history.csv")
        lab = remap_cfg(_engine.run_label(cfg)) if "_engine" in globals() else cfg["name"]
        if is_check(lab):
            continue
        h["model"], h["seed"], h["split_name"], h["loss"] = lab, cfg["seed"], split_name(cfg["split"]), cfg["loss"]
        if splits.get(cfg["split"], {}).get("dataset") == "kth" and cfg.get("windows", 3) != KTH_TRAIN_WINDOWS:
            continue
        hist.append(h)
    if hist:
        H = pd.concat(hist, ignore_index=True)
        for col, ylabel, stem, sub in [("validation_loss", "Validation loss (L1 + 0.5·(1−SSIM))", "fig3_validation_curves",
                                        H.loss.eq("l1_ssim")),
                                       ("val_skill_th", f"Validation skill at t+{MAIN_H} (↑)", "fig3b_validation_skill",
                                        H.get("val_skill_th", pd.Series(np.nan, index=H.index)).notna())]:
            Hs = H[sub]
            if Hs.empty:
                continue
            names = sorted(Hs.split_name.unique())
            fig, axes = plt.subplots(1, len(names), figsize=(min(7.2, 2.7 * len(names)), 2.3), sharey=True, squeeze=False)
            for ax, spn in zip(axes[0], names):
                g = Hs[Hs.split_name == spn]
                for m in order(set(g.model)):
                    s = style(m)
                    for _, sd in g[g.model == m].groupby("seed"):
                        ax.plot(sd.epoch, sd[col], color=s["color"], ls=s["ls"], alpha=0.25, lw=0.8)
                    mean = g[g.model == m].groupby("epoch")[col].mean()
                    ax.plot(mean.index, mean.values, color=s["color"], marker=s["marker"], ls=s["ls"], ms=3)
                if col == "val_skill_th":
                    ax.axhline(0, color="#333", lw=0.8, ls="--")
                ax.set_title(spn)
                ax.set_xlabel("Epoch")
                ax.xaxis.set_major_locator(plt.MaxNLocator(integer=True))
            axes[0][0].set_ylabel(ylabel)
            fig.legend(handles=handles(order(set(Hs.model))), loc="lower center", ncol=2, bbox_to_anchor=(0.5, -0.45),
                       frameon=False)
            fig.suptitle("Validation curves per epoch", fontsize=9, y=1.06)
            CAPTIONS[stem] = (f"{ylabel} per epoch on validation videos (never test videos). Thin lines: seeds; "
                              "thick lines: mean." + (" Dashed line: copy-last-frame." if col == "val_skill_th" else ""))
            save(fig, stem)

    # Fig 4: object vs background error (ground-truth masks used only for scoring)
    if {"foreground_mse", "background_mse"} <= set(MCOLS):
        for (ds, sp, spn), g in SUMM[SUMM.horizon == MAIN_H].groupby(["dataset", "split", "split_name"]):
            models = principal(set(g.model))
            if g["foreground_mse_mean"].isna().all():
                continue
            fig, ax = plt.subplots(figsize=(3.6, 2.4))
            for i, m in enumerate(models):
                r = g[g.model == m].iloc[0]
                col = style(m)["color"]
                ax.errorbar(i - 0.12, r.foreground_mse_mean, yerr=np.nan_to_num(r.foreground_mse_std), fmt="o", color=col, ms=5, capsize=2)
                ax.errorbar(i + 0.12, r.background_mse_mean, yerr=np.nan_to_num(r.background_mse_std), fmt="s", color=col,
                            mfc="white", ms=5, capsize=2)
            ax.set_xticks(range(len(models)), [shown(m, spn) for m in models], rotation=35, ha="right")
            ax.set_ylabel(f"MSE at t+{MAIN_H}")
            ax.legend(handles=[Line2D([0], [0], marker="o", color="#333", ls="", label="Object pixels"),
                               Line2D([0], [0], marker="s", color="#333", mfc="white", ls="", label="Background pixels")],
                      frameon=False)
            ax.set_title(f"{spn}: object vs background error")
            name = f"fig4_object_vs_background_{ds}_{sp}"
            CAPTIONS[name] = (f"MSE on object pixels (ground-truth proposal masks, used only for scoring) and background pixels "
                              f"at t+{MAIN_H}, mean ± s.d. across seeds ({spn}).")
            save(fig, name)

    # Fig 5 + efficiency table: quality vs compute (STEP 7 repeated profiles, one GPU)
    prof_path = ROOT / "analysis" / "selected_profiles.csv"
    PROF = pd.read_csv(prof_path) if prof_path.exists() else None
    if PROF is not None:
        cols = [c for c in ["model", "parameters", "median_ms", "median_ms_min", "median_ms_max", "repeats", "p95_ms",
                            "fps", "peak_gib", "dense_layer_gflops"] if c in PROF]
        eff = PROF[cols].copy()
        eff["params_M"] = eff.parameters / 1e6
        eff["model"] = eff.model.map(lambda m: ARCH_LABEL.get(m, m))   # timing is per architecture
        atomic_csv(TAB / "efficiency.csv", eff)
        print(f"\nEfficiency (batch 1, FP32, 10-frame rollout, GPU profile id: {PROF.hardware_id.iloc[0]})")
        display(eff)
        if "repeats" not in PROF or PROF.repeats.min() < 3:
            WARN.append("Efficiency profile not repeated ≥3 times: rerun STEP 7 (v6) before reporting latency.")
        for (ds, sp, spn), g in SUMM[SUMM.horizon == MAIN_H].groupby(["dataset", "split", "split_name"]):
            g = g[g.model.isin(principal(set(g.model)))].assign(arch=lambda d: d.model.map(arch))
            z = g.merge(PROF.rename(columns={"model": "arch"}), on="arch")
            if z.empty or "lpips_mean" not in z:
                continue
            fig, ax = plt.subplots(figsize=(3.6, 2.6))
            for _, r in z.iterrows():
                s = style(r.model)
                ax.scatter(r.median_ms, r.lpips_mean, s=30, color=s["color"], marker=s["marker"])
                ax.annotate(shown(r.model, spn), (r.median_ms, r.lpips_mean), fontsize=6, xytext=(4, 2), textcoords="offset points")
            pts = z.sort_values("median_ms")[["median_ms", "lpips_mean"]].to_numpy()
            front, best = [], np.inf
            for x, y in pts:
                if y < best:
                    front.append((x, y)); best = y
            if len(front) > 1:
                ax.plot(*zip(*front), color="#999", lw=0.8, ls=":", zorder=0, label="Pareto front")
                ax.legend(frameon=False)
            ax.set_xscale("log")
            ax.set_xlabel("Median inference time per 10-frame forecast (ms, log)")
            ax.set_ylabel(f"LPIPS at t+{MAIN_H} (↓)")
            ax.set_title(f"{spn}: quality vs compute")
            name = f"fig5_quality_vs_compute_{ds}_{sp}"
            CAPTIONS[name] = ("Perceptual error (LPIPS) vs median GPU time for one 10-frame forecast (batch 1, FP32, same GPU, "
                              "median of repeated measurements). Dotted line: Pareto front. " + FOOT)
            save(fig, name)
    else:
        WARN.append("No efficiency profile yet: run STEP 7 (one GPU session) for the efficiency table and Fig 5.")

    # Fig 6 + 6b: real predictions and error maps on held-out videos (deterministic random choice)
    if MAKE_QUALITATIVE and "CACHE" in globals() and orig_split:
        import torch, gc
        from models import Predictor
        from data import Windows
        man = splits[orig_split]
        chosen = {}
        for (mod, seed, sp, win), run in RUNS.items():
            if sp == orig_split and seed == 2024 and mod in principal({mod}) and (run / "best.pt").exists():
                chosen[mod] = run
        ds_q = Windows(CACHE, man["eval"], 30, 1)
        idx = np.random.default_rng(2024).choice(len(ds_q), min(QUAL_SAMPLES, len(ds_q)), replace=False)
        samples = [ds_q[int(i)] for i in idx]
        x = torch.stack([s[0] for s in samples])
        preds = {}
        device = "cuda" if torch.cuda.is_available() else "cpu"
        for m in principal(set(chosen) | {"persistence"}):
            model = Predictor("persistence", device) if m == "persistence" else _engine.load_run(chosen[m], device)[0]
            with torch.inference_mode():
                preds[m] = model(x.to(device), 30).clamp(0, 1).cpu()
            del model
            gc.collect()
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        hs = [1, 5, 10, 20, 30]
        spn = split_name(orig_split)
        for k, (xc, yt, video, start) in enumerate(samples):
            rows = ["ground truth"] + list(preds)
            fig, axes = plt.subplots(len(rows), len(hs) + 1, figsize=(6.2, 1.05 * len(rows)), squeeze=False)
            for r, name in enumerate(rows):
                for c in range(len(hs) + 1):
                    ax = axes[r][c]
                    ax.axis("off")
                    if c == 0:
                        if r == 0:
                            ax.imshow(xc[-1].permute(1, 2, 0).numpy())
                            ax.set_title("last input", fontsize=7)
                        continue
                    h = hs[c - 1]
                    img = yt[h - 1] if name == "ground truth" else preds[name][k, h - 1]
                    ax.imshow(img.permute(1, 2, 0).numpy())
