if RELEASE_GPU_AT_END:
    print("Run finished: progress is saved on Drive (see NEXVIP_REVIEWER_REVISION_V2/RUN_STATUS.md).")
    print("Releasing the GPU runtime in 60 s to stop compute-unit use (interrupt this cell to keep it).", flush=True)
    import time as _t
    _t.sleep(60)
    try:
        _wait_uploads()          # never cut off a checkpoint upload in flight
    except Exception:            # noqa: BLE001
        pass
    from google.colab import runtime
    runtime.unassign()
else:
    print("GPU kept (RELEASE_GPU_AT_END = False). Disconnect it yourself when done: Runtime → Disconnect and delete runtime.")